INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (15481,3,1,'သုံးဆဲ့တစ်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(15482,3,5,'မ—။ မဟုတ်။','ဟမွဲ = မရှိ။ || ဟသုၚ် = မသောက် || ဟအာ = မသွား။ || ‘ဟွံ’ ၏အတိုကောက်ဖြစ်သည်။ မွန်စာပေဟောင်းတွင် အသုံးများသည်။')
,(15483,3,10,'(န) ဟဒယ။ နှလုံး။ စိတ်နှလုံး။',NULL)
,(15484,3,10,'(န) နှလုံး၏တည်ရာ။ နှလုံးအိမ်။ နှလုံးသား။','“ယွံသၟိၚ်ကၞုဲ၊ — ဓဝ်ပန်သီုဖအိုတ်ဂှ် နွံတဴပ္ဍဲဂၠံဟဒယဝတ္ထုတၠအဲရအဴ” ကျာံထိုၚ်သး။ (ဇ—၅၇။ အစွောံ။) = “မျောက်မင်း၊ အလုံးစုံသောလေးပါးကုန်သောတရားတို့သည် သင်၏နှလုံးသား­ ရှိပေ၏” ဟုမိကျောင်းချီးမွမ်း၏။ || “ပ္ဍဲဟဒယဝတ္ထု ပ္ဍဲစိုတ်အဲတေံ ဓဝ်လအေၚ်အဲမသတဴဂှ် တၞဟ်နမရာတ်ညာတ်ဂှ် ဟွံသၟဟ်ရထရမရာတ်” ရသိဂး။ (ဇ—၃၁၃။ အစွောံ။) = “မင်းမြတ်၊ ငါ၏နှလုံးအိမ် ငါ၏စိတ်ထဲ­တည်ရှိသော ငါ၏သည်းခံခြင်းတရားကို သင်မင်းမြတ်မြင်ခြင်းငှာ မတတ်ကောင်း။”')
,(15485,3,3,'ကြီးသော။ အလုံးကြီးသော။','“သဘဴက္ဍိုပ်ဇြုံကၟက် ဟဗာပ်ဒၟံၚ် သၞော်ကြဳ ဗတဍေံတ္ၚံက်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မြွေဖို၏ဦးခေါင်းမည်သည်ကား ကြီး၏။ အရေခွံပါး၏၊ အမြီးကောက်၏။”')
,(15486,3,1,'သင်ပင်။',NULL)
,(15487,3,9,'(အပြော) ငြင်းပယ်ရာ­ သုံးသောစကား။ ဟင့်အင်း။',NULL)
,(15488,3,4,'ဖွင့်သည်။ ဟသည်။','ဟာပါၚ် = ပါးစပ်ဟသည်။ || “မူပပါၚ်နာဲပိုဲ မဟာလဝ်ဂှ်ရော။” (ဇ—၃၈၄။ အစွောံ။) = “သင်၏ပါးစပ်ကို အဘယ်ကြောင့်ဟထားပါသနည်း။”')
,(15488,3,9,'လား။မလား။ သလား။ ဟုတ်၊ မဟုတ်တို့နှင့်ဖြေရသော တိုက်ရိုက်မေးခွန်း၏ နောက်ဆုံးစကား။','‘ကၠုၚ်ဟာ။’ = ‘လာမလား။’ || “စပုၚ်တုဲရဟာ။” = “ထမင်းစားပြီးပြီလား။” || “ထတ်ယုက်ဒၟံၚ်ရဟာ။” = “ကျန်းမာပါသလား။ (ဝါ) ကျန်းမာပါရဲ့လား။”')
,(15489,3,10,'(န) ရယ်ရွှင်ဖွယ်ရာ။ ဟာသ။',NULL)
,(15490,3,1,'ဟိမဝန္တာ။','‘ဟေမဝန်’ ဟူ၍အသုံးများသည်။ || ဂြိုပ်ဟိမဝန် = ဟိမဝန္တာတော။')
,(15491,3,10,'(န) အရှက်တရား။ ဟိရိ။','“ဗ္ၜေံတံဂှ် ဟၟဲကဵုဟိရိသြတ္တပ္ပ။” (ဇ—၃၈၆။ အစွောံ။) =“ဆိတ်တို့မည်သည်ကား ဟိရိသြတ္တပ္ပမရှိကုန်။”')
,(15492,3,4,'မျောသည်။','‘ဆုဟဳဒၟံၚ်ပ္ဍဲဍာ်။’ = ‘ရေထဲတွင် သစ်မျောနေသည်။’')
,(15493,3,4,'လွင့်ပါးသည်။ မျောပါသည်။','“ဟဳဂပဝ်အာကဵုအာရီု။” = “အာရုံ­လွင့်ပါးမျောပါသွားသည်။” || “ဒးဟဳသပဝ်၊ ဇမောဝ်သြဃ။ ဂေတ်ဂေၚ်ဂေတ်ဂေၚ်၊ ဂ္ၚေၚ်ဘဝ။” (လိက်လက္ခဏပိ) = “သံသရာသြဃအယဉ်­ မျောပါလျက် ဘဝသံသရာလည်၏။” || “စိုတ်ဟဳဂပဝ်။” (လိက်မိဍောၚ်ကှ်ေထဝ်။) = “စိတ်လွင့်ပါးသည်။” || “စိုတ်ဟဳသပဝ်၊ ဂေတ်သဝ်ဂျ။” (လိက်ကကၠာ်။ ကောန်ဍး။)')
,(15494,3,10,'(န) မဟာယာနဂိုဏ်းက ထေရဝါဒဂိုဏ်းကို နှိမ့်ချခေါ်သောအမည်။',NULL)
,(15495,3,10,'(န) (စာပေ) ဟီနတ္ထဒေါသ။ ဂုဏ်ကြီးသောအရာကို ဂုဏ်ငယ်အောင် ဖွဲ့ဆိုမိသောအပြစ်။',NULL)
,(15496,3,16,'(န) နက္ခတ်ဗေဒင်အတတ်။ နက္ခတ်ဆရာ။',NULL)
,(15497,3,5,'တဟူးဟူး။ တဟုန်းဟုန်း။','ပၟတ်တူဟူဟူ = မီးတဟုန်းဟုန်းတောက်လောင်သည်။ || ကျာပိုက်ဟူဟူ = လေတဟူးဟူးတိုက်ခတ်သည်။ || “ဗှ်နာဲကြုတ်ဏာ၊ ဒးခြာဇနူ။ မုဟ်ဂြိုဟ်ဟူဟူ၊ သ္တူအာရရဴ။” (လိက်မာဃဒေဝါန်) = “ကြၚ်ဖော်ကွဲကွာနေရသည်ကိုတွေး၍ ရၚ်တွင်း­တဟုန်းဟုန်းတောက်လောင်နေဘိသကဲ့သို့ရှိ၏။” || “ပၟတ်ဟူဟူ၊ တူဟွံတီဟဲ။” (လိက်လက္ခဏပိ) = “မပြတ်မလပ် တဟူးဟူးတောက်လောင်သောမီး။” || “ပ္ဍဲစိုတ်ဟူဟူ၊ တူထဏာန်တဴ။” (လိက်ဇိဝှစက္က) = “စိတ်ထဲ­ တဟုန်းဟုန်းတောက်လောင်ကာ ကူးစက်သွား၏။”')
,(15498,3,4,'(ထဘီ) ဝတ်သည်။','‘ဟဵု’ ရှု။')
,(15499,3,1,'ဟိမဝန္တာ။','ဂြိုပ်ဟေမဝန် = ဟိမဝန္တာတော။')
,(15500,3,10,'(န) ဆောင်းဥတု။','“ဖလုတ်ဝဿန်၊ ဟေမန္တမြော။” (လိက်တလိၚ်ပန်) = “မိုးတွင်းဝဿန်လွန်၍ ဆောင်းတွင်းဟေမန္တ ပွင့်လင်းသည်။”')
,(15501,3,4,'ပြေပျောက်သည်။ ကုန်ဆုံးသည်။ ရပ်စဲသည်။ ငြိမ်းသည်။','‘ပၞာန်ဟဲအာရ။’ = ‘စစ်ပြီးဆုံးသွားပြီ။’ || “ထပှ်တ္ၚဲလောန် သဘၚ်နက်သတ်ဂှ် ဟဲအာ။” (ဇ—၁၁၈။ အစွောံ။) = “ခုနစ်ရက်လွန်၍ နက္ခတ်ပွဲသဘင် ပြီးဆုံးသွား၏။” || “(ဣသိဟံၚ်နၚ်သၟတ်ဗြဴဂှ် နူဍာ်ဂၚ်တုဲ) ကဵုၜံၚ်ပၟတ်လၟုဟ်ဟဲတုဲ ကဵုသစ္ဆုမၞုံကုရှ်—။” (ဇ—၆၃။ အစွောံ။) = “ရသေ့သည် သူငယ်မကို မြစ်ရေမှဆယ်တင်ပြီးလျှင် မီးလှုံစေ၏။ အချမ်းပြေသောအခါ အရသာရှိသောသစ်သီးကို ပေး၏။” || “တြုံဒိုက်ဂတ်ဂှ် ဒှ်အၚပ်သၟိက်ဂွံသုၚ်သုရာ၊ ဂွံသုၚ်သုရာညိတုဲ အၚပ်ဟဲအာရ။” = “ဆင်းရဲသားယောကျာ်းသည် အရက်သောက်လိုသော ချင်ခြင်းသည်ဖြစ်၏။ အနည်းငယ်သောအရက်ကိုသောက်ရပြီးနောက် ချင်ခြင်းပြေသွား၏။” || ‘ကျာဗြဲဂှ်ဟဲအာတုဲ တမာတ်ဂမၠိုၚ်ဂှ်ပဝ်စဴ။’ (ဇ—၁၆၄။ အစွောံ။) = ‘မိုးလေစဲသွားပြီးနောက် လင်းတများသည် ပျံ၍နေရပ်ပြန်ကြကုန်၏။’ || “လဗြဴတုန်လေဝ် ဗ္ၜူသုရာဟဲအာရ။” (ဇ—၃၈၈။ အစွောံ။) = “မိန်းမအိုသည်လည်း အရက်မူးပြေသွား၏။” || “(ဂစေံဒဂိုတ်တံဂှ်) ဒှ်တဴဝါတ်ဂါတ်ကဵုရၚ်သ္ကံ ဟွံဟဲရ။” (ဇ—၃၃။ အစွောံ။) =“ထိုငုံးငှက်တို့သည် အချင်းချင်း ခိုက်ရန်ဖြစ်ကုန်၍ ခိုက်ရန်မငြိမ်းဘဲရှိ၏။” || “ကြဴတဲ ယဲဒိုက်ဟဲတုဲ (စဴကၠုၚ်ဂိုၚ်ကေတ်ဒြပ်ဂှ်ရ။)” (ဇ—၁၇၈။ အစွောံ။) = “နောၚ်အနာရောဂါငြိမ်းသည်ရှိသော် ပြန်လာ၍ ထိုဥစ္စာတို့ကိုယူလော့။”')
,(15502,3,4,'စိတ်ကျေနပ်သည်။ ရောင့်ရဲသည်။ စိတ်ပြေသည်။','“(တရတၟိသမၠီုဂှ်သ္ဂုတ်ၚုဟ်ချေံ ဟွံသေၚ်ကဵုဗဗွဲဓဝ်တုဲ) သကိုပ်သာဂှ် စိုတ်ဟွံဟဲတုဲ ပြာပ်အာဇရေၚ်တရတရေံပၠန်ရ။” (ဇ—၅။ အစွောံ။) = “မိုက်သောရာပြတ်အသစ်သည် မတရားသဖြင့် မြင်းတန်ဖိုးကို ဆုံးဖြတ်သည်ရှိသော် မြင်းကုန်သည်မှူးသည် စိတ်မကျေနပ်သဖြင့် ရာပြတ်ဟောင်းထံသို့ သွားပြန်၏။” || “ဂၞကျာ်စိုတ်ဟွံဟဲတုဲ သၟာန်ဒၟံၚ်ဂၠိုၚ်ကဵုဝါ—။ (ဇ—၃၈၆။ အစွောံ။) = “မိဖုယားသည်စိတ်မပြေ၍ အဖန်တလဲလဲမေးနေ၏။” || “ဆဏအ်တုဲ တန်ရမၞးတံ” နာဲရဲဂှ်ဟီု၊ ညးဂမၠိုၚ်ဂှ်ဟွံဟဲစိုတ်—။ (ဇ—၄၉၃။ အစွောံ။) = “ဤမျှဖြင့် တော်တန်တော့” ဟု ခေါင်းဆောင်ကဆို၏။လူအများက စိတ်မကျေနပ်သေး—။ || “ဆဝွံတုဲ စိုတ်အဲဟဲရ။” (ဇ—၃၄၃။ အစွောံ။) = “ဤမျှဖြင့် ငါစိတ်ကျေနပ်ပြီ။” || “ဗဵုဒ္ၚောဝ်တဴဟွံတီဖဲ ဟွံတီဟဲစိုတ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ရှုစား၍မဝနိုင် မရောင့်ရဲနိုင်။”')
,(15503,3,4,'ပြေပျောက်သည်။ ပျောက်ပြယ်သည်။ ကုန်ဆုံးသည်။','“သုၚ်လဝ်အရက်ဂှ် ဟဲဇးအာရ။” = “အရက်သောက်ထားသည်မှာ အမူးပြေပျောက်သွားပြီ။” || “ပ္ကဴဂှ်ကှ်အာတုဲ သၟူမြမောဝ်ဟဲဇးအာရ။” = “ထိုပန်းသည် ခြောက်သွားပြီးနောက် အမွှေးရနံ့ပျောက်ပြယ်သွားသည်။”')
,(15504,3,4,'ရပ်စဲသည်။ ကုန်ဆုံးသည်။','“ဗြဲဂူဟဲဍးအာတုဲရ။” = “မိုးစဲသွားပြီ။”')
,(15505,3,4,'ရပ်စဲသည်။ ကုန်ဆုံးသည်။ ပြေပျောက်သည်။','“ယွံမဒ္ဒဳ၊ — ဗြဲမွဲဝှ်ပိဂိတု သလေပ်ဟဲဗြဟ်ကီု၊ ဗြဲမတ်အဲဝေသန္တဝ်ဝွံ မူစိဂိတုသၞာံပယာံအခါ တီဟဲဗြဟ်ရောမဒ္ဒဳ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “အဘယ်မဒ္ဒီ၊ သုံးလတစ်ဝါရွာသောမိုးသည် စဲတတ်စမြဲဖြစ်သော်လည်း ငါဝေဿန္တရာ၏မျက်ရည်မိုးသည်ကား ဘယ်သောအခါ အဘယ်ကာလမှ ရပ်စဲပါငြားအံ့နည်း။” || “သဘၚ်ဟဲ ဗြဟ်၊ ထပှ်တ္ၚဲလောန်။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ခုနစ်ရက်လွန်၍ ပွဲသဘင်ပြီးဆုံးသည်။” || “မိဒးကြအ်လၞီ၊ ဟွံတီဟဲဗြဟ်။” (လိက်ကောန်သၟိၚ်ဝါရဝေါၚ်သ။ အစွောံ။) = “ပူပန်သောကဖြင့် တွေဝေမူးမိုက်နေသည်မှာ မဆုံးနိုင်ဘဲရှိ၏။” || “အဒိနာဲဆာန်၊ ပ္ကာန်က္ဍိုပ်မွဲဒၞဳ။ လမုဟ်ဟဲဗြဟ်၊ ညိဟွံဗှ်သ္ၚဳ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “အစဦးစွာက တစ်ခုတည်းသောခေါင်းအုံး­ ခေါင်းချင်းယှဉ်၍ အိပ်စက်ခဲ့ကြသော်လည်း ယခုမူ (ချစ်ခြင်း) ကုန်ဆုံး၍ စိုးစဉ်းမျှပၚ်မအောက်မေ့မကြည့်တော့။”')
,(15506,3,4,'(ဒေါသ၊ အာဃာတ၊ ရောဂါဝေဒနာစသည်) ပြေငြိမ်းသည်။ ပျောက်ပြယ်သည်။','“ဒေါသဟဲလလံအာ။” = “ဒေါသပြေပျောက်သွားသည် (ငြိမ်းသွားသည်။)” || “ယဲဟဲလလံအာ။” = “ရောဂါပျောက်ကင်းသွားသည်။”')
,(15507,3,4,'ပြေပျောက်သည်။ ငြိမ်းပျောက်သည်။','“လမောင်ဟဲသွာ၊ ဂွံသမာဓိ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “အမောပြေ၍ စိတ်သမာဓိကိုရ၏။” || “ဒှ်ဒၟံၚ်လၞီ၊ ဟွံတီဟဲသွာ။” (လိက်ပယးအနိစ္စ) = “ငြိမ်းပျောက်ရမှန်းမသိသောသောက ဆက်တိုက်ဖြစ်နေ၏။” || “ဍာ်ရမတ်အဲ၊လအ်ဂွံဟဲသွာ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ငါ့မျက်ရည်ခန်းပျောက်သည့်တိုင်အောင်။”')
,(15508,3,4,'ပြေပျောက်သည်။ ကုန်ဆုံးသည်။','“ဗြဴမ္ဂးဝွံ ဇၞော်ကဵုပဏတ် ပဏတ်ပြဟ် ပဏတ်တုဲ လအ်ဟဲဟောံသန်။” (ဇ—၆၃။ အစွောံ။) = “မိန်းမမည်သည် အမျက်ကြီး၏၊အမျက်ထွက်မြန်၏၊ အမျက်ထွက်ပြီး အမျက်ပြေပျောက်နိုင်ခဲလှ၏။”')
,(15509,3,4,'၁။ စုအုံသည်။ စုရုံးသည်။','“ကၠိက်ဂမၠိုၚ် မိၚ်ကၠချိုတ်ရဂးတုဲ စိုတ်မိပ်ဟောကၠုၚ်ဖျုန်ကၠကၠိက်ဂမၠိုၚ်စအိုတ်ရ။” (ဇ—၂၈၃။ အစွောံ။) = “တောဝက်အပေါင်းတို့သည် ကျားသေပြီဟု ကြားလတ်သော် ဝမ်းသာ၍ စုအုံလာကြပြီးလျှင် ကျားသားကို (အလုအယက်) စားကြကုန်၏။” || “ဒှ်ရသာ်ဂှ် ညံၚ်ပိုဲအာရပ်ဣသိ (စၞာဲ) ဂှ်ညိရ” ဂးတုဲ သီုကၠိက်ဂမၠိုၚ်ဂှ် ဟောအာကဵုဣသိပၠန်ရ။ (ဇ—၄၉၂။ အစွောံ။) = “ထိုသို့တပြီးကား ထိုရသေ့စဉ်းလဲကို သွားဖမ်းကြကုန်အံ့” ဟုတောဝက်အပေါင်းတို့သည် ထိုရသေ့ဆီသို့ စုအုံပြေးသွားကြပြန်၏။ || “ဂၠုၚ်ရဲပသီ တိုန်ဂၚ်လတူတိုၚ်လၞၚ် လ္ၚဵုထစေၚ်လ္ၚဵုဗြံ သၟိၚ်လဂန်အိန်ညာတ် ဂၠုၚ်ပၞာန်ပၞုက်ဗဒမံၚ်တံဂှ် ဟောတိတ် သီုဇကုသၟိၚ်လဂန်အိန်ဗတိုက်။” (အကြီုကမြဴလွဳရာဇာဓိရာဇ်) = “ပုသိမ်သားတို့၏လှေများသည် ၚုတ်တိုင်များနှင့်ငြိ၍ အချို့လှေများစောင်း၍ အချို့မှောက်ကုန်သည်ကို လဂွန်းအိန်မြင်လျှင် ဝှက်ထားသောမိမိလှေများ တစ်ဟုန်တည်းစုအုံထွက်လာပြီး လဂွန်းအိန်ကိုယ်တိုင် တိုက်ခိုက်၏။”')
,(15509,3,4,'၂။ ဆူညံသည်။ ဟစ်ကြွေးသည်။','‘ဗရုနာနာ — ဗြုဟောဇၟာပ်ဂၠံၚ်။’ (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ) = ‘အသံမျိုးစုံတို့ဖြင့် နည်းမျိုးစုံဆူညံနေ၏။’')
,(15510,3,4,'ဆူညံသည်။ အုတ်အုတ်ကျက်ကျက်ဖြစ်သည်။ အုတ်အော်သောင်းတင်းဖြစ်သည်။','“ကွဳကဵုကွဳ ဇံၚ်ကဵုဇံၚ် ရမျှာၚ်ဟောကၠံၚ် ဒက်ဒၟံၚ်ဇံၚ်အဆက်အဆက်အိုတ်ရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “များစွာသောလှည်း များစွာသောထမ်းစင်တို့ဖြင့် အုတ်အုတ်ကျက်ကျက်အသံဆူညံလျက် အဆက်ဆက် ထမ်းစင်ဖွဲ့နေကြကုန်၏။” || “ဂစေံပြဝါ၊ ဂၠာဲအာသီုသီု။ ဟောကၠံၚ်လဒု၊ထဥဂြဴကြီု။” (လိက်သုဝဏ္ဏသာံ။ မာံသေၚ်။) = “ငှက်အပေါင်းအဖော်တို့သည် အားထုတ်ရှာသွားကြရင်း အုတ်အော်သောင်းတင်းဆူညံလျက် တွန်မြည်ကျူးရင့်နေကြကုန်၏။”')
,(15511,3,4,'ဆူညံသည်။ ဟစ်ကြွေးသည်။ သောသောညံသည်။','“ဒဒှ်ဒဳမတိုန် ဟွံကဵုသေံတံမိၚ်ဗရုဒဳတုဲ နွံအသံတၠညးကဵုတက်ဖံမံၚ် ဗရုကၞုသြၚ်ခပဵုခရာ ကဵုပါၚ်ဟောဂြာဒၟံၚ် ဒဒှ်ဒဳမတိုန် သေံတံဟွံတီသက်သက်။” (အကြီုရာဇာဓိရာဇ်) = “ဒီရေတက်သောအသံကို ထိုင်းတို့မကြားစေရန် သူ့ရှင်အမိန့်ရှိ၏။ စည်၊ မောင်း၊ ခရုသင်း၊ တံပိုး၊ ခရာတို့ကို တီးမှုတ်စေလျက် ငြာသံပေးဟစ်ကြွေးဆူညံနေရာ ဒီရေတက်သည်ကို ထိုင်းတို့လုံးဝမသိလိုက်ကြ။ || “ဗဵုလဗးကၠံၚ်၊မံၚ်ဆာၚ်ဟောဒြာ” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “စစ်သည်ဗိုလ်ပါများ စုဝေးဆူညံ၍ ဗုံမောင်းသံတို့ သောသောညံနေ၏။” || “ဍာ်ဂၚ်ဂှ်ဇွောဝ်အာ ဇီုဒးဒဵုတၟံတံဂှ်တုဲ ဗြုဗြန်နာနာ ဟော ဂြာဂမြိၚ်။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “မြစ်ရေစီးဆင်း၍ ကျောက်တောင်တို့ကို ထိတိုက်ခတ်မိသည်ရှိသော် အမျိုးမျိုးအသံမြည်၍ ဆူညံမြည်ဟည်းနေ၏။” || “ကောန်သမ္ဘာရော၊ယာံတဴဟောဒြာ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “သားမယားတို့ ငိုကြွေးသံဆူညံနေ၏။” || “ဂစေံပြဝါ၊ ဟောဒြာဗြုကၠံၚ်။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ငှက်အပေါင်းအဖော်တို့သည် အော်မြည်ဆူညံကုန်၏။”')
,(15512,3,16,'(န) ၁။ ဟူးရား။ နက္ခတ်ဗေဒင်အတတ်။ နက္ခတ်ဗေဒင်ဆရာ။','“သဝ်လေပ်ဗိန္ဒော၊ဟောရာကိုန်သၟတ်။ ဗဟူသိပ္ပ၊ ဂၠိုၚ်တလကွတ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ဗိန္ဒောဆေးပညာကို တတ်သောသမားတော်များ၊ ဟူးရားအတတ်ကို တတ်သောပညာရှင်များ များစွာရှိ၏။”')
,(15512,3,16,'(န) ၂။ ဆေးသမား။ သမားတော်။','“ဟောရာတီယဲ၊ ဘဲဝေဒနာ။ ပြကိုဟ်ကၞပ်၊ တဗျဂုန်ကၠာ။”= “ဆေးသမားသည် ရောဂါဝေဒနာနှင့် ဒြဗျဂုဏ်းဆေးကျမ်းဂန်ကို သိနားလည်၏။”')
,(15513,3,1,'သာမန်လက္ခဏာ။ (?)','“ဆဂှ်ဟွံသေၚ် ကာလကောန်အဲမသလးပတိသန္ဓိဂှ်လေဝ်ညံၚ်ဟောဟာလိုက်တံညးဂမၠိုၚ်ဟွံသေၚ်သွံ။” (သၠပတ်သုရသာ) = “ငါ၏သားသည် မွေးဖွားလာစဉ်ကလည်း လောကလူသားအပေါင်းတို့၏ သာမန်လက္ခဏာကဲ့သို့ မဟုတ်ပါတကား။” || “ကောန်အဲသုရသာဝွံဂှ် ဟောဟာသတ်ဂမၠိုၚ်ဟွံသေၚ်၊ ကောန်အဲသုရသာဝွံ တြုံတလဣဓိဗလတြုံတလပါရမဳရောၚ်။” (သၠပတ်သုရသာ) = “ငါ၏သားသုရသာသည် သတ္တဝါတို့၏သာမန်လက္ခဏာမျိုးဟုတ်၊ ငါ၏သားသုရသာသည် တန်ခိုးရှင် ပါရမီရှင်တည်း။” || “ပ္ဍဲကောန်မရှာတ်တၠတိဇၞော်သုရသာဝွံ မက္တဵုဒှ်ကောန်မရာတ်မ္ဂးဝွံ ဟောဟာညးဂမၠိုၚ်ဟွံသေၚ်၊ တၟေၚ်လောန်နူညးရောၚ်။ —ကောန်မရှာတ်ဝွံ ယဝ်ရမရှာတ်စွံလဝ်ပ္ဍဲဍုၚ်မ္ဂးဝွံ သ္ဒဟ်သပုန်ရ။ ယဝ်ရဟွံဒှ်သပုန်ဍုၚ်ဝွံသြုန်အာရ။ ယဝ်ရဟွံဒှ်သာ်ဂှ်မ္ဂး ဟွံသေၚ်ဒွံဒွါမရာတ်ဟာ၊ ဟွံသေၚ်ဒွံဒွါဂၞကျာ်ဟာ ဒှ်ဗိုန်ရ။” (သၠပတ်သုရသာ) = “အရှင်မင်းမြတ်၏သားတော်သုရသာသည် လူတကာတို့၏သာမန်လက္ခဏာမျိုးမဟုတ်၊ သူတကာတို့ထက်ထူးခြား၏။ အရှင်မင်းမြတ်၏သားတော်ကို တိုင်းပြည်­ထားပါကသူပုန်ဖြစ်လတ္တံ့။ သူပုန်မဖြစ်ပါက တိုင်းပြည်ပျက်သုန်းရလတ္တံ့။ ထိုသို့မဖြစ်ပါက အရှင်မင်းမြတ်ကိုသော်၄င်း မိဖုရားကိုသော်၄င်း ထိခိုက်ခြင်းအမှန်ဖြစ်လတ္တံ့။”')
,(15514,3,5,'စုစုဝေးဝေး။ တစ်ခဲနက်သောအသံဖြင့်။ (?)','“ဂမှဳတံဂး၊ ထိုၚ်သးဟောဟော။ကျာ်တြဲမိၚ်ရော၊ နသောတဒွါ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “တစ်ခဲနက်သောအသံဖြင့် ရဟန်းများပြောဆိုချီးမွမ်းသည်ကို မြတ်စွာဘုရားသည် နားတော်ဖြင့် ကြားတော်မူ၏။”')
,(15515,3,5,'ဆူဆူညံညံ။','“ပွမလုဟ်ကဵုသုၚ်စဝေၚ်ဂြိုၚ် ဗဵုပေဲါသဘၚ်လှ်ေဂယှ်ေ ဟောဟောဂြာဂြာဂၠိုၚ်လောန်။” (ဓမ္မဝိဘာဂ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) =“သောက်စားကစားရယ်ရွှင်၍ ဆူဆူညံညံ အဆိုအကပွဲသဘင်ကြည့်ရာ­ တပ်မက်အပျော်ကြူး ခြင်း။”')
,(15516,3,5,'၁။ (အမောဆို့၍) အသက်ရှူသံပြင်းစွာဖြင့်။','“ဟွံတီပုၚ်သွ၊ လီုစိတ္တဇဴ။ ဆီကျာဆောတ်ယောၚ်၊ လၟောၚ်ဟဴဟဴ။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “စိတ်ပျက်၍ ထမင်းဟင်းလည်းမစားနိုင်။ သွေးလေဖောက်ပြန်၍ အသက်ရှူသံပြင်းစွာဖြင့် အမောဆို့၏။” || “ယီုဒၟံၚ်ဟဴဟဴ၊ဟီုဗၠာၚ်ယာံဗၠာၚ်၊ ရမျှာၚ်လေဝ်ကၠဴ။” (လိက်သောဝါနနဟောၚ်) = “အသံပြင်းပြင်းဖြင့် အသက်ရှူလျက် ပြောရင်းငိုရင်းဖြင့် အသံလည်း မပီမသဖြစ်လာ၏။” || “ပိုဲသီုလမောင်၊ ဍောၚ်ဒၟံၚ်ဟဴဟဴ။” (လိက်သောဝါနနဟောၚ်)')
,(15516,3,5,'၂။ (မီး၊ ဒေါသစသည်) တဟုန်းဟုန်း။','“ဍုန်ပုၚ်သွသၟတ်၊ ပၟတ်ဟဴဟဴ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “မီးတဟုန်းဟုန်းဖြင့် ထမင်းဟင်းချက်၏။”')
,(15516,3,5,'၃။ (အနံ့) တဟောင်ဟောင်ဖြင့်။','“အိက်ကၞံပေၚ်ဂၠ၊ မသဟဴဟဴ။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “ချေးသေးတို့ပြည့်လျက် တဟောၚ်ဟောၚ်နံစော်၏။”')
,(15517,3,1,'နံနံပင်။ နံနံရွက်။','ဟံဗံကြုက် = တရုတ်နံနံပင်။ || ဟံဗံသေံ = ရှမ်းနံနံပင်။')
,(15518,3,1,'ဟင်္သာငှက်။',NULL)
,(15519,3,1,'ဟံသာဝတီပြည်။ ပဲခူးမြို့။',NULL)
,(15520,3,4,'ပြည့်လျှံသည်။','“နဇမောဝ်ဍာ်မဇၞော်ဂှ် ဇွောဝ်သကိုဟ်စှ်ေကၠုၚ် ဟးအာသြၚ်ကြုၚ်ၜါလပါ်တုဲ—။” (ဇ—၅ဝ၄။ အစွောံ။) = “ကြီးစွာသောရေအယဉ်သည် ဒလဟောစီးဆင်းသည်ရှိသော် မြစ်ကမ်းနှစ်ဖက်တို့ကို ပြည့်လျှံသွား၏။” || “ဇြဟာန်သၟိန်ဗွဲတဏှာဂှ် ကုညးမၞုံစိုတ်မဟးကဵုဇကုဂှ်စိုတ်ဇကုမ္ဒးဟးကဵုညးကီုရ။” (ဇ—၃၃၃။ အစွောံ။) = “မိမိ­ အချစ်တဏှာပြည့်လျှံသောစိတ်ရှိသူအား မိမိသည်လည်း ပြည့်လျှံသောအချစ်စိတ်ကို ထားရပါမည်။” || (အာလုပ်) အယ်။ ဟယ်။ရယ်။ အို။ || ‘ဟးကောန်ဂၠုတေမဳယာဲ၊ ပနာဲကၞပ်ဒၟံၚ်ကဵုယာဲရောလေဝ်ကောန်။’ (ဇ—တေမဳ။ အစွောံ။) = ‘အိုသားကြီးမောင်တေမိရဲ့၊ ဘာကြောင့်မယ်မယ့်ကို နှုတ်ဆိတ်နေပါသနည်း။’')
,(15521,3,4,'နှမြောတသသည်။',NULL)
,(15522,3,1,'တဟားဟားရယ်သံ။','“ပ္ဍဲဂှ်လဗြဴ၊ ဂြိုၚ်တဴဟးဟး။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) =“ထိုအခါ မိန်းမအိုသည် တဟားဟားရယ်၏။”')
,(15523,3,4,'(ထမင်းဟင်းစသည်) တူးသည်၊ တူးလောၚ်သည်။','‘သ္ၚေက်’ ရှု။')
,(15524,3,1,'ကျီ။ သိုလှောင်ရန်နေရာ။','ဟၚ်အှ်ော = ထင်းထားသောနေရာ။ || ဟၚ်သြောံ = စပါးကျီ။ || “တိုန်အာလတူဟၚ်သြောံတုဲ—။” (ဇ—၁၉၉။ အစွောံ။) = “စပါးကျီပေါ်သို့တက်၍—။”')
,(15525,3,1,'ကြာသိမ်။',NULL)
,(15526,3,4,'၁။ တွေဝေထိုင်းမှိုင်းသည်။','“သံမုယှန္တိ၊ ပ္ဍံဝိဝိၚ်ဟိၚ်ဟိုပ် ဝိုတ်တဴဓဝ်သတိအိုတ်။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “တွေဝေထိုင်းမှိုင်း၍ သတိမေ့လျော့ကုန်၏။” || “အဲဍိက်ကောန်လၟ၊ ဟွံဒညညှာ။ ဗက်ဂၠာဲပန်ဂြိုပ်၊ ဟိၚ်ဟိုပ်မှာရာ။ ဟွံဂွံစရ၊ ပုၚ်သွအဟာ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “မုဆိုးသားဖြစ်သောတပည့်တော်သည် မကြောက်မရွံ့ တောလိုက်ပစ်ခတ်ရာ တွေဝေထိုင်းမှိုင်း မျက်စိလည်လမ်းမှား၍ အစာရေစာလည်းမစားရ။”')
,(15526,3,4,'၂။ ပူဆွေးအားငယ်သည်။','“ဟွံဂွံညာတ်ကောန်၊ လောန်ထောန်ဟိၚ်ဟိုပ်။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) =“သားကိုမမြင်ရသဖြင့် (မိခင်ခမျာ) အလွန်တရာ ပူဆွေးအားငယ်နေရှာ၏။” || “ကောနာဲဒဇန်၊ပ္ကီုဒန်ကဵုမ။ မိဒးဟိၚ်ဟိုပ်၊ ဒေါဝ်ဂြိုပ်ဟေမ။ မိအိုတ်ဂန္ဓ၊ တ္ၚဲဝွံရကောန်။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “ချစ်သား၊ သင့်နောင်တော်တို့သည် ရက်စက်၍ သင့်ကိုအန္တရာယ်ပြုခဲ့ပြီ။ အမယ့်ခမျာတောကြီးအလယ်­ ပူဆွေးအားငယ်လျက် ဤယနေ့ပင်လျှင် သေပွဲဝင်ရတော့မည်။” || “တိုန်ဒဵုဂွါန်တၟအ်၊ တရဴလအ်စိုပ်။ သီုမဟိၚ်ဟိုပ်၊ ဒေါဝ်ဂြိုပ်ညးၜါ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) =“တစ်တောင်ဆင်းတစ်တောင်တက်ဖြင့် သွားသည့်ခရီး ရောက်နိုင်ခဲလှ၏။ ချစ်သူနှစ်ဦးတို့သည်တောကြီးလယ်­ ပူဆွေးအားငယ်နေရရှာ၏။”')
,(15527,3,5,'(မောင်းသံကဲ့သို့) တဒုန်းဒုန်း။ တဒူဒူ။ (မြည်သည်) ။','“မံၚ်ဗြုဟုၚ်ဟုၚ်။” (လိက်သၟိၚ်အသး။ နန္ဒသာရ။) = “မောင်းသံတဒူဒူမြည်သည်။” || “တက်မံၚ်ဟုၚ်ဟုၚ်၊ လုံဍုၚ်ဒိုဟ်စှ်။” (ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “မြို့လုံးအနှံ့ အရပ်ဆယ်မျက်နှာလုံး တဒူဒူမောင်းတီး၏။”')
,(15528,3,5,'သာလျှင်။','“ဨကရာတ်ဟေၚ် ပ္တန်ဍုၚ်ရ။” = “ဘုရင်သာလျှင် မြို့တည်၏။”')
,(15528,3,9,'(ကြိနောက်ဆက်။ ဝါကျနောက်ဆက်။) အဓိပ္ပါယ်ကိုလေးနက်စေသောစကားလုံး။','“လောဘဂၠိုၚ်မ္ဂး အပဲါပန်စဴဒှ်သ္ၚိဇၞူဟေၚ်။” = “လောဘများလျှင် အပါယ်လေးဘုံသည် နေရန်နေရာဖြစ်လိမ့်မည်။” || “မိတ်မဆာန်ဟေၚ်ကဵုဒှ်ကီုရ၊ စာ်စ္ဍးသာဲသ္ၚောဲနူပညာ မိတ်ဂှ်ဟွံပြဲဟေၚ်။” (ဇ—၄၄။ အစွောံ။) = “ချစ်သောအဆွေခင်ပွန်းပၚ် ဖြစ်စေကာမူ ပညာကင်းမဲ့လျှင် ထိုအဆွေခင်ပွန်းသည် မမြတ်။”')
,(15529,3,4,'၁။ မလိုတမာဖြစ်သည်။ မုန်းတီးသည်။ မနှစ်မြို့။','“ဗော်တဳဒိတ္ထိ၊စိုတ်ဂိယောၚ်ယာ။ ညာတ်ကျာ်ဟေၚ်ဟဟ်၊ ဟွံဒှ်သဒ္ဓာ။” (ဇၞးမ္ၚးဒစာံသာ်။ ပါလိတ။) = “ဒိတ္ထိအပေါင်းတို့သည် မြတ်စွာဘုရားရှင်ကို မြင်လတ်သည်ရှိသော် မလိုတမာမုန်းတီးစိတ်နာ၍ သဒ္ဓာတရားမဖြစ်။”')
,(15529,3,4,'၂။ ပူဆွေးသည်။ စိတ်မချမ်းမြေ့။','“ဟွံဒးစိတ္တ၊ ဟောံဇြတူယဲ။ စိုတ်ဒှ်ဟေၚ်ဟှ်၊ မုက်ကှ်ကဝဲ။” (လိက်သု ပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။) = “မျက်နှာမသာမယာဖြင့် ညိုးငယ်ပူပန်၏၊ ပူဆွေး၍ စိတ်မချမ်းမြေ့ မျက်နှာညှိုးခြောက်၏။”')
,(15530,3,4,'၁။ ဆယ်ယူသည်။','‘ဟံၚ်အှ်ောပ္ဍဲၜဳ။’ = ‘မြစ်ထဲတွင် ထင်းဆယ်သည်။’')
,(15530,3,4,'၂။ ကယ်ဆယ်သည်။','“ကျာ်တြဲဟံၚ်ဖျဴသတ္တအ် ဍုၚ်ဇၞော်နိဗ္ဗာန်ရ။” = “မြတ်စွာဘုရားသည် သတ္တဝါများကို နိဗ္ဗာန်ပြည်ကြီးသို့ ကယ်ပို့တော်မူ၏။”')
,(15531,3,4,'ကယ်ဆယ်သည်။ ကယ်တင်သည်။','“ဒဒှ်ဗောဓိသတ်ဟံၚ်ပြာ်လဝ်တုဲ မဂွံလမျီုဂှ်ဣသိ (ဗောဓိသတ်) ဟီုကဵုညးအိုတ်ရ။” (ဇ—၇၃။ အစွောံ။) = “(ထိုမင်းသားအား) ဘုရားလောင်းကယ်တင်ထား၍ အသက်ရသောအဖြစ်ကို ဘုရားလောင်းရသေ့သည် လူများအားပြောပြ၏။”')
,(15532,3,1,'ကြာသိမ်။','“မ္ၚး (ဍာ်) ဂှ် ဂြိုပ်ဟံၚ်ရံသက်သက် မွဲယောဇနာ ဗိုၚ်ကၠောံဒၟံၚ်ရ။” (ဇ—၅၁၄။ အစွောံ။) = “ရေ၏အခြားမဲ့­ တယူဇနာအနာံရှိသော ကြာသိမ်တောသည် — ခြံရံ၍တည်၏။” (ညောင်ကန်) || ‘ဟၚ်ရံ’ နှင့်အတူတူ။')
,(15533,3,4,'သတ္တဝါတို့ကို ကယ်ဆယ်သည်။ —ကယ်ချွတ်သည်။','“ဒဒှ်ကျာ်ဂွံဂြၚ်ဓဝ် ဟံၚ်သတ်တအ်ဂမၠိုၚ်ဂှ် အဲရာဒၞာမိက်တုဲ အဲပ္တုဲဒါန်ရအဴ။” (ဇ—၃၄ဝ။ အစွောံ။) = “ဘုရားအဖြစ် တရားကိုသိမြင်ကာ သတ္တဝါအပေါင်းကိုကယ်ချွတ်ရန် တောင့်တဆုပန်၍ ငါအလှူပေး၏။”')
,(15534,3,1,'ပျားကြီးတစ်မျိုး။ ပိတုန်း။',NULL)
,(15535,3,1,'အာဇာနည်မြင်း။ ဝလာဟကမြင်းမျိုး။','“ကၠဵုဂှ် ညံၚ်ပရှ်ချေံဟဇ္ဇနဲကီုဒှ်တုဲထဍေၚ်ဗက်ကၠုၚ်သေဋ္ဌဳဂှ်ရ။” (ဇ—၅၃၅။ အစွောံ။) = “ထိုခွေးသည် အာဇာနည်မြင်း အတိုင်းအရှည်ရှိသည်ဖြစ်၍ ထိုသူဋ္ဌေးကို လိုက်သည်ရှိသော်—။” (ညောင်ကန်) || “ချေံရတ်ကၠုၚ်နူဟဇ္ဇနဲရ။” (ဇ—၄၇၉။ အစွောံ။) = “ဝလာဟကမျိုးမှ မြင်းရတနာသည် ရောက်၏။” (ညောင်ကန်)')
,(15536,3,1,'၁။ ဗိုင်းငင်သောရစ်ဘီး။ ငင်စက်။','၂။ (ပါသက်) တစ်တောင်အတိုင်းအတာ။ (၁၈) လက်မ။ (ပါဠိ—ဟတ္ထ)')
,(15537,3,1,'ကြံရည်ကြိတ်စက်။ ဝါကြိတ်စက်။',NULL)
,(15538,3,11,'(န) လက်တစ်ကျော့။ လက်တစ်ကွင်း။ နှစ်တောင့်တစ်ထွာ။ (ပါဠိ—ဟတ္ထပါသ)',NULL)
,(15539,3,1,'တစ်ဆဲ့ကိုးလက်မခွဲရှိသော တစ်တောင်အတိုင်းအတာ။',NULL)
,(15540,3,10,'(န) ဟာသ။',NULL)
,(15541,3,10,'(န) (စာပေ) ဟဿရသ။ ရွှင်လန်းရယ်မြူးမှုရသ။',NULL)
,(15542,3,1,'မြစ်အတွင်းရေတိမ်သောနေရာ။',NULL)
,(15543,3,1,'ချေဆတ်ရာတွင်မြည်သံ။ ဟတ်ချိုး။',NULL)
,(15544,3,4,'‘သ္ၚိတ်ဇြ’ ရှု။',NULL)
,(15545,3,4,'စိုးရိမ်းသည်။ ကြောင့်ကြသည်။ ပူပန်သည်။','‘သ္ၚိတ်သ္ၚဲ’ || ‘သ္ၚိတ်သ္ၚောဲ’ နှင့်အတူတူ။ || “ပ္တန်လဝ်စိုတ်ရ၊ ပဒှ်ဟိတ်ဟဲ။ သၟာဓိဂှ်ပၠန်၊ သ္ဂောံတန်မၚ်မွဲ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “စိတ်ကိုတည်ငြိမ်အောင်ထားကာ မပူပန်မကြောင့်ကြလေနှင့်။ စိတ်သမာဓိတည်ရအောင် စောင့်ရှောက်ထားပါ။”')
,(15546,3,1,'မွေးလိမ်ပျား။',NULL)
,(15547,3,4,'၁။ လျော့ကျသည်။ ယုတ်လျော့သည်။ ဆုတ်ယုတ်သည်။','“အာယုက်သတ်တံဟုတ်စှ်ေ။” = “သတ္တဝါတို့၏သက်တမ်းလျော့ကျသည်။” || “ဍာ်မှာသၟိတ်ဝွံဂှ် ဍေံဟုတ်အာဟွံမာန်ဟေၚ်ရ။ ဍာ်မှာသၟိတ်ဝွံဂှ် ဍေံပေၚ်တဴလၟိုန်ဟေၚ်။” (ဇ—၂၉၆။ အစွောံ။) = “ဤသမုဒ္ဒရာရေသည် မယုတ်လျော့နိုင်။ ဤသမုဒ္ဒရာရေသည် ပြည့်မြဲတိုင်းပြည့်၏။”')
,(15547,3,4,'၂။ ပျက်စီးသည်။ဆုံးရှုံးသည်။ ကွယ်ပျောက်သည်။','“ယွံခမဳတံ၊ ဒေဝဒတ်မဟုတ်အာ နူလာဘသက္ကာရဂှ် ဆလၟုဟ်ဟွံသေၚ်၊ အတိက်တေံကီုလေဝ် ဒးဟုတ်အာနူလာဘသက္ကာရဂှ် ဒှ်တုဲရခမဳတံ” ကျာ်တြဲဂး။ (ဇ—၂၄၁။ အစွောံ။) = “ရဟန်းတို့၊ ဒေဝဒတ်သည် ယခုအခါ­သာလျှင် မိမိ­ဖြစ်ပြီးသော လာဘသက္ကာရကို ကွယ်စေသည်မဟုတ်သေး။ ရှေး­လည်း ကွယ်စေဘူးသလျှင်ကတည်း။” (ညောင်ကန်) || “ညးဗၞိက်လီုသမၠီုဂှ် ဒးဟုတ်အာနူထးထဝ် ၚုဟ်မွဲလက်ဂှ်ရ။” (ဇ—၃။ အစွောံ။) =“ထိုမိုက်သောရွဲကုန်သည်သည် အဖိုးတစ်သိန်းထိုက်သောရွှေခွက်မှ ဆုံးရှုံးသွားရ၏။” || ‘လဟုတ်’ (န) လည်းရှု။')
,(15548,3,4,'အနံ့ခံသည်။','“ကၠဵုဂှ် ထဍေၚ်ဗက်ကၞိမွဲ၊ ကၞိဂှ်လုပ်အာပ္ဍဲကသိုၚ်တုဲ ကၠဵုဂှ် ဟောတ်တုဲဂွး ဟောတ်တုဲဂွးကသိုၚ်ဂှ်ရ။” = “ထိုခွေးသည် ကြွက်တစ်ကောင်ကို ပြေးလိုက်၍ ကြွက်ကတွင်းထဲဝင်သွားရာ ခွေးက အနံ့ခံကာ အနံ့ခံကာ ထိုတွင်းကိုယက်သည်။”')
,(15549,3,11,'(န) ၁။ အကြောင်း။ အကြောင်းရင်း။','“ဟိုတ်ဍေံဟွံကၠုၚ်ဂှ် မၞးတီဟာ။” =“သူမလာသောအကြောင်းရင်းကို သၚ်သိပါသလား။”')
,(15549,3,11,'(န) ၂။ ပြဿနာ။ အခက်အခဲ။','“က္တဵုဒှ်တဴဟိုတ်ဇၞော်ကဵုဒြဟတ်ရ။” = “ပြဿနာအကြီးအကျယ်ဖြစ်သည်။” || “ကိစ္စမၞိဟ်တံဂၠိုၚ်လောန်သန်၊မမိက်ကဵုဟိုတ်မွဲမွဲ မဒှ်ကဵုကုဍေံနွံရ။” (ဇ—၁၇၇။ အစွောံ။) = “လူတို့­ ကိစ္စများမြောင်၏။ လူတို့­ အကြောင်းတစ်ခုခု (ပြဿနာတစ်ရပ်ရပ်) ပေါ်ပေါက်လာနိုင်၏။” || “သၞာံဂှ် မၞိဟ်ဂမၠိုၚ် ဒှ်ဟိုတ်နာနာသာ်ရ။” (သၠပတ်ကွိက်ကၠိ) = “ထိုနှစ်တွင် လူတို့သည် ပြဿနာအမျိုးမျိုးဖြစ်၏။”')
,(15550,3,1,'အကြောင်းကိစ္စ။ အခက်အခဲ။ ပြဿနာ။','“ပ္ဍဲကာလဟိုတ်ကိစ္စမွဲမွဲ မက္တဵုဒှ်ဂှ် တၠပညာဟေၚ် ညးမဒးဂၞပ်ရ။” (ဇ—၉၂။ အစွောံ။) = “နက်နဲသောပြဿနာဖြစ်လတ်သော် ပညာရှိကို အလိုရှိကုန်၏။” (ညောင်ကန်)')
,(15551,3,7,'ထိုကြောင့်။','“ဍေံယဲအာ၊ ဟိုတ်ဂှ်ရ ဍေံဟွံဂွံအာဘာ။” = “သူဖျားသွားသည်။ ထို့ကြောင့်သူကျောင်းမသွားရပါ။”')
,(15552,3,1,'ဖြစ်ရပ်။ အကြောင်းရင်း။ အကြောင်းတရား။','“အတိုၚ်ဟိုတ်ဒဒှ်ဂှ် မိဟီုကဵုရ။” (ဇ—၁၆၃။ အစွောံ။) = “ထိုအကြောင်းရင်းကို မိခင်ပြောပြ၏။” || “ဟိုတ်ဒဒှ်ဂှ် တၠအဲဟီုကဵုအဲညိ။” (ဇ—၄၄ဝ။ အစွောံ။) = “ထိုဖြစ်ရပ်ကို အကျွန်ုပ်အား သင်ပြောပြပါ။”')
,(15553,3,6,'ကြောင့်။ အတွက်ကြောင့်။','“ဟိုတ်နူဗြဲ သြောအ်ခိုဟ်ရ။” = “မိုးကြောင့် စပါးကောင်းသည်။” || “ဟိုတ်ဒၟာနူပိုန်ဒြပ်အိုဿီုတံဂှ် လ္ပကဵုအဲဒးက္တဵုဒှ်လောဘညိ။” (ဇ—၄၈ဝ။ အစွောံ။) = “အလုံးစုံသောဥစ္စာတို့ကြောင့် ငါ့အား လောဘမဖြစ်ပါရစေနှင့်။” || “အဲဝွံဟိုတ်ဒမာနူဗြဴတုဲ မဒးကၠုၚ်ဒုၚ်ဒဒိုက် မဒှ်ဍိက်တဏှာ—။” (ဇ—၅၃၁။ အစွောံ။) = “ငါသည်မိန်းမအတွက်ကြောင့် ဒုက္ခလာခံစား၍ တဏှာ၏ကျေးကျွန်ဖြစ်ရ၏။”')
,(15553,3,9,'သောကြောင့်။','“ဟိုတ်နူညးကၠောန်လဝ် ညးဂွံဂ္ဇအ်စၜိုဟ်ၜိုဟ်ရ။” = “သူအလုပ်လုပ်ထားသောကြောင့် သူအေးအေးထိုၚ်စားရသည်။”')
,(15554,3,4,'အကြောင်းအကျိုး။','“ဂလာန်တၠအဲမဟီုဂှ် မစိုန်သကီုတဴကေုာံဟိုတ်ဖဵုရောၚ်။” (ဇ—၃၂၃။ အစွောံ။) = “သင်ပြောသောစကားသည် အကြောင်းအကျိုးနှင့်ပြည့်စုံ၏ (အကြောင်းအကျိုးဆီလျော်၏။)” || “ဒဒှ်ဟိုတ်ဖဵုဍေံဂှ် ညးဟွံတီတုဲ ညးဟွံပတှ်ေ—။” (ဇ—၂၈၈။ အစွောံ။) =“ထိုအကြောင်းအကျိုးဖြစ်စဉ်ကို သူတစ်ပါးတို့မသိကြကုန်သဖြင့် မယုံကြကုန်။”')
,(15555,3,7,'အကြောင်းကား။',NULL)
,(15556,3,4,'မေ့လျော့သည်။ သတိလစ်ဟင်းသည်။ သတိလက်လွတ်ဖြစ်သည်။ ပေါ့ဆသည်။','“ယွံအမာတ်၊ ပိတ္ၚဲဂတတုဲ အမာတ်ဂွံဒှ်ဨကရာတ်ရ။ သမ္ဘာအမာတ် ဂွံဒှ်ဂၞကျာ်အဂ္ဂမဟေသဳရ။လ္ပဟိုတ်မာဲ ပသတိဗလညိ” ရသိဂး။ (ဇ—၂၈၄။ အစွောံ။) = “အမတ်၊ ရှေ့သုံးရက်­ အမတ်သည် ဘုရင်ဖြစ်ရလတ္တံ့။ အမတ်၏မယားသည် မိဖုယားခေါင်ကြီးဖြစ်ရလတ္တံ့။ မမေ့လျော့နှင့်၊သတိဝီရိယရှိပါစေ” ဟုရသေ့ဆို၏။ || “အဃောသၟိၚ်ဝါရေဝ်ရောဝ်မဟိုတ်မာဲတဴဂှ် ကောန်စဴၜါဂှ်တ္ၚီုဗာ်ဂစိုတ်ကၠေံသၟိၚ်ရ။” = “ဝါရီရူမင်း သတိလစ်ဟင်းစဉ် မြေးနှစ်ယောက်က မင်းကြီးအားထိုးခုတ်သတ်ဖြတ်လိုက်ကြ၏။” || “ဂြောဝ်ဂှ် ဒေပ်လဝ်ဖျုန်တုဲ ဂြောဝ်ဂှ်ဟိုတ်မာဲအာတုဲ ကၠဵုပ္ဍဲသ္ၚိဂှ် စကၠေံဖျုန်ဂှ်ရ။” (ဇ—၅၃၇။ အစွောံ။) = “ဤသို့ထားအပ်သောအမဲကို စားတော်ချက်သည်မေ့လျော့သဖြင့် မင်းအိမ်­မွေးသော ခွေးတို့သည်စားကုန်၏။”')
,(15556,3,1,'မေ့လျော့ခြင်း။ သတိလစ်ဟင်းခြင်း။ ပေါ့ဆခြင်း။','မသက္ကုဟိုတ်မာဲ၊ မသက်ကဵုဟိုတ်မာဲ = မေ့လျော့ခြင်းကင်းသည်။ || “(ပဋိပတ်မပြဲဂမၠိုၚ်ဂှ်) ပတၠတုဲ ဇၟာပ်သရၚ်သီုဖအိုတ် လ္ပတရံၚ်ဟိုတ်မာဲညိ။” (ဇ—၄၉။ အစွောံ။) = “မြတ်သောအကျင့်တို့ကို ပိုင်ဆိုင်ကျင့်သုံး၍ အမှုကိစ္စဟူသမျှ­ မေ့လျော့ခြင်းကို မကြီးရင့်ပါစေနှင့်။”')
,(15557,3,1,'(ပေါ်ပေါက်လာသော) အရေးကိစ္စ။ အကြောင်းကိစ္စ။ တစ်စုံတစ်ခုသောပြဿနာ။','“ဟိုတ်မွဲဖဵုၜါက္တဵုဒှ်မ္ဂး ကေတ်အဆက်ကဵုအဲ ဗွဲမပြဟ်ညိ။” = “ပြဿနာတစ်စုံတစ်ခုပေါ်ပေါက်လျှင် ငါနှင့်အမြန်အဆက်အသွယ်ယူပါ။” || “မၞးတအ်ပစိုတ်၊ ဟိုတ်မွဲဖဵုၜါ။” (လိက်ဇိဝှစက္က) =“အကြောင်းကိစ္စတစ်စုံတစ်ခု ပေါ်ပေါက်လာမည်ကို သင်တို့သတိပြုကြလော့။”')
,(15558,3,6,'အပေါ်။ အပေါ်သို့။',NULL)
,(15558,3,5,'သောအခါ။',NULL)
,(15558,3,4,'(သူတစ်ပါးမရယူနိုင်ရန်) ကာဆီးရယူထားသည်။ ကာဆီးကာဆီးလုပ်သည်။','“ဒၞာဲဂ္ဇအ်ဂှ် ညးဟန်လဝ်သွက်ရဲညး။” = “ထိုထိုၚ်ရန်နေရာကို သူ့သူငယ်ချင်းအတွက် သူရယူထားသည်။” || “(ခမဳဂှ်) မၞုံဂၞပ်မဇၞော်ဂှ်ဒှ်တုဲ — ဘာၜါပိဋ္ဌာန်ဂှ် ဟန်လဝ်တုဲ ပ္ဍဲဘာမွဲဂှ် က္ဍိုၚ်ဇကုမွဲစွံလဝ်၊ ပ္ဍဲဘာမွဲဂှ် ဒၞပ်ဇကုမွဲစွံလဝ်၊ ပ္ဍဲဘာမွဲဂှ် ဗဗေၚ်ဇကုမွဲစွံလဝ်—။” (ဇ—၄ဝဝ။ အစွောံ။) = “ထိုရဟန်းသည် အလိုကြီးသည်ဖြစ်၍ နှစ်ကျောင်းသုံကျောင်းတို့­ ကာဆီးနေရာယူထားပြီးလျှင် တစ်ကျောင်း­ မိမိထီးကိုထား၏၊ တစ်ကျောင်း­ မိမိဖိနပ်ကိုထား၏၊ တစ်ကျောင်း­ မိမိသပိတ်ကိုထား၏။” || “ညံၚ်စာၚ်ဂဒပ်ကောန်၊ဃောဟန်ခမှာဲ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ဥကိုဝပ်သောကြက်မကြီးကဲ့သို့ ဥကို သူတစ်ပါးမနှောင့်ယှက်နိုင်အောင် ကာဆီးကာဆီးလုပ်နေတုန်းဖြစ်၏။”')
,(15559,3,4,'(သူတစ်ပါးမရယူနိုင်အောင်) မိမိကိုယ်ပိုၚ်ပြု၍ တားဆီးသည်။ ကာဆီးကာဆီးလုပ်သည်။','ဂစေံမယှဂှ် “ဣဝွံဒြပ်အဲရောၚ်၊ ဣဝွံဒြပ်အဲရောၚ်” ဍေံဂးတုဲ ဍေံဟန်တာဒၟံၚ်ဂစေံဂမၠိုၚ် မဒၟံၚ်ဂကောံဍေံဂှ်ရ။ (ဇ—၃၉ဝ။ အစွောံ။) = “မယှကမည်သောငှက်သည် ဤကားငါ့ဥစ္စာ၊ ဤကားငါ့ဥစ္စာဟုဆိုကာ မိမိနှင့်အတူ ကျက်စားကုန်သောငှက်များအား အစာတို့ကိုမစားရန် တားဆီး၏။” || “မၞိဟ်ဂမၠိုၚ်ဂှ် ဂကူသၟိၚ်ကီု ဂကူဗမၞးကီု ညးဒိုက်ညးလွေဟ်ကီု ဍေံဟန္တာလဝ်ဣဝွံဒှ်ဒြပ်အဲ ဣဂှ်ဒှ်ဒြပ်အဲဂးတုဲ ဍေံဟန္တာဓနာလဝ်ရ။” (ဇ—၂၁၉။ အစွောံ။) = “လူတို့မည်သည်ကား မင်းမျိုးတို့သည်၄င်း ပုဏ္ဏားမျိုးတို့သည်၄င်း သူဆင်းရဲ၊ ကုန်သည်လူတန်းစားတို့သည်၄င်း ဤကားငါ့ဥစ္စာ ထိုဟာကားငါ့ဥစ္စာဟူ၍ မိမိကိုယ်ပိုၚ်ပြု၍ သူတစ်ပါးတို့အား ပိတ်ပၚ်တားဆီးတတ်ကုန်၏။”')
,(15560,3,4,'(ကာမပိုၚ်မိန်းမက မိမိလင်ယောကျ်ားကို အခြားမိန်းမများနှင့် မနီးကပ်မဆက်ဆံစေလို၍) ဝန်တိုဟန့်တားသည်။','“ဣဗြဴဂှ် ဟန်တြုံကွေံ။ တြုံဍေံတက်ကျာကဵုဗြဴတၞဟ်မ္ဂး ဍေံဟွံဒးစိုတ်ရ။” = “ထိုမိန်းမသည် လင်ကို ဟန့်တားကာဆီးတတ်သည်။ မိမိလၚ်က အခြားမိန်းမတို့နှင့်တကွ စကားပြောဆိုလျှင် မကြိုက်ပါ။” || ‘ဟန်ဗြဴ’ (ကြိ) လည်းရှု။')
,(15561,3,1,'အမှိုက်ပုံ။ အညစ်အကြေး။','ဋ္ဌာန်ဟန်ဗန် = တံမြက်ချေးစွန့်ရာအရပ်။ အမှိုက်စွန့်ပစ်ရာနေရာ။ || “(သၟိၚ်) စိုပ်အဿမာပိုတ်တုဲ ညာတ်ဟန်ဗန်ပေၚ်ဒၟံၚ်ဋ္ဌာန်ဂှ်တုဲ—။” (ဇ—၂၅၁။ အစွောံ။) = “(မင်းသည် ကျောင်းသင်္ခမ်းသို့ရောက်၍) အမှိုက်တို့ဖြင့်ပြည့်သော ကျောင်းကိုမြင်၍—။” (ညောင်ကန်) || “(သုၚ်သုရာတုဲ) ဒးသတိက်အကြာဟန်ဗန်။” (ဇ—၅၁၂။ အစွောံ။) =“သေရည်အရက်ကိုသောက်၍ အမှိုက်သရိုက်အကြား­ အိပ်ရ၏။” || “(ဍေံချိုတ်တုဲ) ဇိုၚ်ဍေံၜါဂှ်ညးရပ်ကေတ်တုဲ ပ္ဍဲဋ္ဌာန်ညးထောံဟန်ဗန်ဂှ် အာထောံကၠေံရ။” (ဇ—၂၄၃။ အစွောံ။) = “(သူသေပြီး၍) ခြေတို့ကိုကိုင်၍ တံမြက်ချေးအမှိုက်စုရာအရပ်­ စွန့်ပစ်၏။” (ညောင်ကန်) || “ပုၚ်စၞတံဂှ် ခ္ဍာ်ဂှ်ဟွံဂွံစတုဲ ဗြုဒၟံၚ်အက်အက်တုဲ ပဝ်စှ်ေဂၠာဲစအကြာဟန်ဗန်တုဲ မဂွံစရ။” (ဇ—၃၃၉။ အစွောံ။) = “ကျီးသည် ခဲဘွယ်ဘောဇဉ်ကို မရလတ်သော် ကာကာမြည်လျက် ပျံသွား၍ မစင်စွန့်ရာမြေ­သက်၍ အစာကိုယူ၏။” (ညောင်ကန်)')
,(15562,3,4,'(ကာမပိုၚ်ယောကျာ်းက မိမိမယားကို အခြားယောကျာ်းများနှင့် မနီးကပ်မဆက်ဆံစေလို၍) ဝန်တိုဟန့်တားသည်။','“တြုံဂှ် ဟန်ဗြဴကွေံ။ ဗြဴဍေံ အလဵုအာအာ ဍေံဟွံဖျေံစိုတ်ရ။” =“ထိုယောကျာ်းသည် မိမိမယားကို ဝန်တိုဟန့်တားကာဆီးတတ်သည်။ မယားဘယ်သွားသွားစိတ်မချပါ။” || ‘ဟန်တြုံ’ (ကြိ) လည်းရှု။')
,(15563,3,4,'(တိရစ္ဆာန်အဖို) မိတ်လိုက်ရာတွင် အခြားပြိုင်ဘက်များအား ကာဆီးကာဆီးလုပ်သည်။ ကာမအာရုံ­ ဝန်တိုသည်။','“ဂၠဴဥသဘမွဲဂှ်ဗက်လွၚ်၊ ဂၠဴဥသဘသ္အာၚ်မွဲ ဒြၚ်ဍေံမသ္ကေက်တဴဂှ်ညာတ်တုဲ ဟန်အရီုတုဲ ကၠုၚ်စုက်စတ်စုတ် ဂၠဴဥသဘဗက်လွၚ်ဂှ်—။” (ဇ—၄ဝ၈။ အစွောံ။) = “တစ်ခုသောဥသဘနွားသည် မိတ်လိုက်၏။ ဦးချိုချွန်ထက်သော အခြားဥသဘနွားသည် မြင်သည်ရှိသော် ကာမအာရုံ­ ဝန်တိုသဖြင့် မိတ်လိုက်သောဥသဘအား ထိုးဝှေ့၏။”')
,(15564,3,1,'အစုအဝေး။',NULL)
,(15564,3,5,'တကွ။ အတူတကွ။ (ပါဠိ—သဒ္ဓိံ)',NULL)
,(15564,3,9,'ကြိယာကိုလေးနက်စေသောစကားလုံး။','“ဟွံဂွံစိုပ်ဟာန်၊ ဍုၚ်နိဗ္ဗာန်ၚဲ။ အာရီုတဏှာ၊ သ္ကေက်သ္ကာလောန်တဲ။” (လိက်အနုသာသန) = “နိဗ္ဗာန်ဝေး၍ မရောက်နိုင်ဘဲ တဏှာအာရုံ အလွန်ပြင်းထန်ဆဲဖြစ်၏။”')
,(15565,3,4,'မူသည်။ ဟန်လုပ်သည်။','“လ္ပပဒၟံၚ်ညံၚ်ကဵုကၟုဲ လ္ပဟာန်ဒၟံၚ် လုပ်စထောံပုၚ်ဖဴပိုဲညိရ။” = “ဧည့်သည်လို ဟန်လုပ်မနေနှင့်။ ငါတို့နှင့်အတူ ထမင်းဝၚ်စားလိုက်ပါ။”')
,(15566,3,4,'၁။ ဆင်ယင်သည်။ တန်ဆာဆင်သည်။ အလှပြင်သည်။','“သီုသရာဲမဍိုက်ကွဳ ကဵုသၠိုက်ခြပ် ရပ်ဂဒံၚ်သၠုဲသၠာ်ထဝ်သြန် ကဵုဗဂန်စၞာံကၠဗြန်ဇာဒိသိုၚ် ကဵုကျိုၚ်ကျဝ်ဟာန်ဇာ—။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ရထားစီးသူရဲတို့ကို ချပ်ဝတ်တန်ဆာဝတ်စေ၍ ကြေးနီ၊ ကြေးဝါ၊ရွှေ၊ ငွေဖြင့်လုပ်သော ကာလက်နက်တို့ကို ကိုင်ဆောင်စေ၍ ကျား၊ သစ်၊ ခြင်္သေ့ရေတို့ကိုယူ၍ဝတ်စားဆင်ယင်စေကုန်၍—။” || ကျိုၚ်ကျဝ်ဟာန်ဇာ (ပါဠိ—သိကရ) || “အဲဆအဲရဂးတုဲ မအာစိုပ်အာကာရ ပွမဂိုၚ်ကေတ်လဝ်ဓဝ်မာန သလောၚ်သပဝ်နာနာ ဟာန်ဇာတဴဒၟံၚ်အိုတ်ရ။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ငါမှငါဟု မာနထောင်လွှားကာ အမျိုးမျိုးကြည်နူး၍ (ခန္ဓာအပုပ်ကောင်ကို) အလှပြၚ်နေကြကုန်၏။”')
,(15566,3,4,'၂။ လှပသောဟန်အမူအရာဖြင့် ကသည်။ မခို့တရို့ကသည်။','“ဒုၚ်ပ္တိုန်တဲၜါ၊ လှ်ေဟာန်ဇာတဴ။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) = “လက်နှစ်ဖက်ကိုတၚ်ပြီး မခို့တရို့ကသည်။”')
,(15566,3,4,'၃။ မြူးထူးသည်။ ပျော်ရွှင်သည်။','“ပတ္တစာရဳ၊ ပ္ဍဲဒေါဝ်လွဳမာန်။ဗြဴတၠဒါန်၊ ဟာန်ဇာတဴတုန်။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ပဋာစာရီသည် စည်းစိမ်ဘုံဗိမာန်လယ်­ ပျော်ရွှင်စံမြန်း၏။” || “ဍေံညာတ်ဗဵုပၞာန်၊ ဟာန်ဇာမှောင်မှဴ။ ဃဵုလုပ်အာတဴ၊ ရဴကေသရာ။” (လိက်သၚ်ဂဒါ။ သဳလဝန္တ။) = “စစ်သည်ဗိုလ်ပါတို့ကို မြင်သည်ရှိသော် မြူးထူးပျော်ရွှင်လျက် ကေသရာခြင်္သေ့ကဲ့သို့ အလျင်စလိုလျှောက်ဝင်သွား၏။” || “အမာတ်ဒကိုပ်ပၞာန်၊ ဟာန်ဇာမှောင်မှဴ။ မိၚ်အသံရ၊ တၠက္ဍိုၚ်ပ္ကဴ။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ဘုရင့်အမိန့်ကိုကြားသည်ရှိသော် အမတ်စစ်သူကြီးတို့သည် ဝမ်းသာပျော်ရွှင်ကုန်၏။” || “လ္ၚဵုလှ်ေကွာဲရ၊ ဇွတဳလဇျာန်။ အိုတ်ကောန်ဍုၚ်ကွာန်၊ မိပ်တဴဟာန်ဇာ။” (လိက်ဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “ဘုန်းကြီးပျံပွဲတော်­ အချို့လူတို့သည် ကကြကုန်၏။ အားလုံးသောပြည်သူများသည် ပျော်ရွှင်မြူးထူးကြကုန်၏။”')
,(15566,3,1,'အမူအရာ။ ဟန်ပန်။','“ဣတ္ထိဘာဝရုပ်မ္ဂ္ဂးဂှ် ရုပ်မဒှ်ဟိုတ်အကာဲအရာသဏူဌာန်ဟာန်ဇာဗြဴတံရောၚ်။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) = “ဣထ္တိဘာဝရုပ်မည်သည်မိန်းမတို့၏အမူအရာသဏူဌာန်ဟန်ပန် အကြောင်းခံဖြစ်သောရုပ်တည်း။” || “ပုရိသဘာဝရုပ်မ္ဂ္ဂးဂှ်လေဝ် ရုပ်မဒှ်ဟိုတ်ဗီုပြၚ်သဏူဌာန်ဟာန်ဇာတြုံတံရောၚ်။” (အဘိဓမ္မတ္ထဒဳပနဳ။ ဂရိုက်သာံ။) =“ပုရိသဘာဝရုပ်မည်သည်လည်း ယောကျာ်းတို့၏ပုံသဏူဌာန်ဟန်ပန်အမူအရာ အကြောင်းခံဖြစ်သောရုပ်တည်း။”')
,(15567,3,1,'အသွင်အပြင်။ အမူအရာ။ ဟန်ပန်။','ဟာန်ဗာန်ဗြဴ = မိန်းမ၏အသွင်အပြင်။ မိန်းမ၏အမူအရာ။ မိန်းမ၏ဟန်ပန်။ (ပါဠိ—ဣတ္ထာကပ္ပ)')
,(15567,3,4,'၁။ အသွင်ဆောင်သည်။ သရုပ်ဆောင်သည်။ ဟန်လုပ်သည်။','ပွမလှ်ေဟာန်ဗာန် = ဟန်လုပ်ကပြခြင်း။ (ပါဠိ—လာသန)')
,(15567,3,4,'၂။ဆင်ယင်သည်။ တန်ဆာဆင်သည်။ (?)',NULL)
,(15568,3,10,'(နဝိ) မကောင်းသော။ ယုတ်ညံ့သော။ ယုတ်မာသော။ ကျက်သရေယုတ်သော။','“သၟတ်ဗြဴမၞုံကဵုရုပ်မဟိဏ္ဏ။” = “ကျက်သရေမရှိသော အရုပ်ဆိုးသည့်မိန်းမငယ်။” || “လောဘဂၠက်စိုတ်၊ ဒှ်ပြိုတ်ဟိဏ္ဏ။” (လိက်ဟတ္ထိပါလ။ အစွောံ။) = “လောဘစိတ်ထူပြောသ ဖြင့် ကျက်သရေမရှိသော ယုတ်ညံ့သောပြိတ္တာဖြစ်၏။” || “သၟိၚ်မာဟိန်ဏ၊ ဇက်ကၠုၚ်ပပၞာန်။” (လိက်ပ္တံပါရမဳ။ အစွောံ။) = “ယုတ်မာသောမာရ်နတ်မင်းသည် ဘုရားအား လာရောက်စစ်ခင်း၏။” || “ထဝ်သြန်ဂှ်ဗိုန်၊ ပ္တိုန်ဖျေံစရ။ ကဵုမွဲကေတ်ပိ၊ စိုတ်ကၠိဟိဏ္ဏ။” (လိက်ကောန်ဂစေံပိ။ နာဲဗျူ။) = “ရွှေငွေတို့ကို အတိုးချစား၍ တစ်ဆပေးသုံးဆယူသော ညစ်ယုတ်သောစိတ်။” || “ထောံဒဂေတ်အဴ၊ မိမဗဴလ။ ဟွံဗိုန်ဆတ္တဝ်၊ လဝ်စိုတ်ဟိဏ္ဏ။” (လိက်ကာလထေ) = “မိဘဘွားဘိုးတို့၏အကျင့်ကိုစွန့်၍ မမြဲမမြံ ယုတ်မာသောစိတ်ထားရှိ၏။” || “ဒေပ်စိုတ်ဟိဏ္ဏ၊ ပဝယုတ်မာ။” (လိက်ကာလထေ) || “မသအုဲပါၚ်၊ ရမျှာၚ်ဟိဏ္ဏ။ ဟီုဂလာန်ကွေံ၊ ညးဟွံပ္တေဟ်ဂျ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ပါးစပ်ပုပ်နံ၍ အသံယုတ်ညံ့၏၊ စကားပြောသည်ကို သူတစ်ပါးမယုံ။”')
,(15569,3,3,'၁။ အရုပ်ဆိုးသော။ အကျည်းတန်သော။','“ပူဂဵုဂှ် ဟွံဒးဟိန် ဟွံဒးပရေအ် ဟွံဒးဒိုက်ဟွံဒးဝါတ် ဂေါဝ်ကျေဝ်အာ။” (ဓမ္မဝိဘာဂ။ ပြကိုဟ်မန်ဍုၚ်သေံ။) = “ထိုပုဂ္ဂိုလ်သည် အကျည်းမတန် အရုပ်မဆိုး မဆင်းရဲမနွမ်းပါး လှပတင့်တယ်လိမ့်မည်။” || “ဝုတ်ကဵုလဗြဴ၊ မူရဴစိုတ်ဒး။ဂေါဝ်ကဵုဟိန်ကွေံ၊ ရာမဒးဂၞပ်။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “အပျိုနှင့်အအို အဘယ်သူ့ကို ကြိုက်ပါသနည်း။ ရုပ်လှသည်နှင့်အရုပ်ဆိုးသည် အဘယ်ကို နှစ်သက်ပါသနည်း။”')
,(15569,3,3,'၂။ ယုတ်သော။ ယုတ်ညံ့သော။ ယုတ်မာသော။','“ညးလ္ၚဵုဂှ်၊ ဒှ်ဗြာန်သေၚ်ဟာ။ ဂစိုတ်သတ်ရ၊ပမံၚ်ကိုင်ကာ။ — လမျီုသတ်ပၠန်၊ ဟွံတီနန္တာ။ ဟွံဆာန်သတ်ကၠာ၊ စိုတ်ဟိန်ပါပ။” (လိက်ကာလထေ) = “အချို့သူတို့သည် မုဆိုးလုပ်ကာ သတ္တဝါတို့ကိုသတ်ခြင်းဖြင့် အလုပ်အကိုင်ပြုနေကြကုန်၏။ မရေမတွက်နိုင်သော သတ္တဝါများ၏အသက်ကိုသတ်၍ သတ္တဝါတို့ကိုမချစ် ယုတ်မာသောစိတ်ရှိ၏။”')
,(15570,3,3,'အကျည်းတန်သော။ သန့်ပြန့်စင်ကြယ်ခြင်းမရှိသော။ ရွံရှာဖွယ်ဖြစ်သော။ ကျက်သရေမရှိသော။','“ပြိုတ်မၞုံကဵုသၟူအမြာဲဟွံဒးရး မၞုံကဵုသာ်ဇကုမဟိန်ဗိန်တဴ။” (သၚ်္ခါရဘေဒနဳ။ ဝိန္ဒသာရ။) = “အနံ့အသက်မကောင်းသော ညစ်ပတ်ပေရေသော ကိုယ်အရောင်အသွေးရှိသောပြိတ္တာ။” || “ဍိက်ကုန်မဂပ်ဂဝ်ယုတ်မာ မဂပ်ဂဝ်က္ဍုဟ်မၠေအ်ဟိန်ဗိန်ဇအိုတ်စိုတ်ဂှ်လေဝ် (ဗြဴဝွံ) ဍေံသိပ်ဂၠိပ်ဟုဲဟာဲကီုသွံ။” (ဇ—၅၃၆။ အစွောံ။) = “ညစ်တီးညစ်ပတ် ရွံရှာဖွယ်ကောင်းသောကျွန်ငကုန်းမျှကိုလည်း ဤမိန်းမသည် မှီဝဲပေါင်းဖက်ပေ၏။” || “ဒလိဒ္ဒါ၊ ဍေံမဝါတ်ဂါတ်ဟိန်ဗိန်ဒိုက်ဒိန်ကာဲကၞာဲအိုတ်။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ညစ်ပတ်စုတ်ပြတ်ဆင်းရဲနွမ်းပါး၏။” || “ပွမၞုံအတ္တဘဴမယုတ်ဟိန်ဗိန် မဒှ်ဂဍုဟ်ညး။” (ဓမ္မဒဳပနဳ။ မာံရွှေငိုး။) = “သူတစ်ပါးတို့ရွံမုန်းဖွယ်ရာ ယုတ်ညံ့ညစ်ပတ်သော ကျက်သရေမရှိသော ခန္ဓာကိုယ်ရှိခြင်း။” || “ရုပ်သာ်ဟိန်ဗိန်၊ ရမျှာၚ်ဟိဏ္ဏ။” (လိက်ကကၠာ်။ ကောန်ဍး။) = “ရုပ်ရည်အကျည်းတန်၍ အသံယုတ်ညံ့၏။”')
,(15571,3,4,'ငှဲ့သည်။','“သၞေဝ်ၜိုဟ်လဝ်ပ္ဍဲထၟာဲဂှ် ဟေန်ထောံဍာ်ညိ။” = “အိုးထဲတွင်ပြုတ်ထားသောဟင်းရွက်ကို ရေငှဲ့ထုတ်လိုက်ပါ။” || ဟေန်ဍာ်ဍဵု = ထမင်းရည်ငှဲ့သည်။ || “ဟေန်ဍာ်က္ဍဵုစိ၊စိုပ်တိဟွံလအ်။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “ထမင်းရည်ငှဲ့၍ မကြာမြေသို့ရောက်၏။” || “ဟေန်ကဵုဂၞာ ဆာဲထောံကဵုဓရဳ။” (သၠပတ်ပေါရဏာံ။ အစွောံ။) = “အုန်းမှုတ်နှင့်ငှဲ့ယူ၍ စဉ့်အိုးကြီးနှင့်သွန်ပစ်သည်။”')
,(15572,3,4,'(အကြားအာရုံကို) ချိုသာစေသည်။ သာယာစေသည်။','“ရမျှာၚ်ဗြီုညဳ၊ ဝါစဳသဒ္ဒ။ဍိုန်ဍောတ်လမော၊ ဟေန်စဝ်သောတ။ ရှ်သုဘာသိုတ်၊ အမြိုတ်ဓမ္မ။” (လိက်ဝိဓူရ) = “(မြတ်စွာဘုရား၏) မဟာဗြဟ္မာ၏အသံကဲ့သို့ သိမ်မွေ့ကာ နားသောတအာရုံ­ သာယာချိုသာစေတတ်သော ကောင်းသောစကားအရသာရှိသော အမြိုက်တရားတော်။”')
,(15573,3,4,'ဖျက်ဆီးသည်။',NULL)
,(15574,3,4,'ခြိုးခြံသည်။ ချွေတာသည်။ (ဥစ္စာ) ဆည်းပူးသည်။','“သတ္တံပ္ဍဲလိုက်ဝွံဂှ် ဟွံဗစာရဏာကဵုခန္ဓသၚ်္ခါရတုဲ သဳခေန်ဟေန်ဆာဲဂလိုၚ်ဒြပ်ဂှ်ရ။” (ဇ—၃၉ဝ။ အစွောံ။) = “လောကသတ္တဝါတို့သည် သၚ်္ခါရတရားကို မဆင်ခြင်ကုန်ဘဲ စစ်စီခြိုးခြံချွေတာစုဆောင်း၍ ဥစ္စာကိုသာတိုးပွားစေကုန်၏။” || “မအဲလအဲတံတေံဂှ် — ပဗၞိက်ဇိက်ဗ္ၚဟေန်ဆာဲဒြပ် ဂွံဒြပ်ဂှ်သီုဒဒိုက်ရောၚ်။” (ဇ—၅၃၅။ အစွောံ။) = “ငါ၏အဘအဘိုးတို့သည် ကုန်သွယ်လယ်လုပ်၍ ဥစ္စာကိုခြိုးခြံလျက် ဆင်းရဲငြိုငြင်စွာဖြင့် ဥစ္စာကိုရကုန်၏။” || “ညံၚ်လစမဟေန်ဆာဲလဝ်ဍာ်ဂှ် တၞဟ်နလစဟွံသေၚ်။ တၞဟ်နသကဵုသတ်တၠတဟၚ်သုၚ်ရောၚ်။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ရေအိုင်သည်ရေကို ခြိုးခြံသိမ်းဆည်းထားခြင်းသည် ရေအိုင်အတွက်မဟုတ်။ ရေငတ်သောသတ္တဝါတို့သောက်ရန်အတွက်သာဖြစ်၏။”')
,(15574,3,1,'နိုးကြားခြင်း။ ခြိုးခြံခြင်း။','(တၠညးသုခေါဒါယ ထိုၚ်သးမဂဒူလောန်သန်။ “ကောန်မန်ဝွံ ဍေံနွံကဵုဟေန်ဆာဲလွဳပရာကွေံ။” (အကြီုကမြဴလွဳရာဇာဓိရာဇ်) =သောက္ကတဲမင်းသည် မဂဒူးအား အလွန်ချီးမွမ်း၏။ “ဤမွန်လုလင်သည် ခြိုးခြံခြင်းရှိ၍ လုံ့လဝီရိယနှင့်ပြည့်စုံ၏။” || “(မဂဒူဝွံ) မတၚအ်လ္ပအ် က္တဵုပြဟ်ၚုဟ်လောဲ နွံကဵုလွဳလွတ်ဟေန်ဆာဲ ဒးကဵုစိုတ်ဨကရာဇ်။” (အကြီုရာဇာဓိရာဇ်) = “မဂဒူးသည် နိုးကြားဖျတ်လတ်၏။ စောစီးစွာထ၍နိုးလွယ်၏။ လုံ့လရှိခြင်း ခြိုးခြံသောအကျင့်ရှိခြင်းကြောင့် ဘုရင့်အကြိုက်ဖြစ်၏။”')
,(15575,3,4,'(အကြားအာရုံကို) ချိုသာစေသည်။ သာယာစေသည်။','“ကြဝိတ်ကဵုကွဴ၊ နှဴဆိုင်သဒ္ဒ။ ဒှ်မွဲရမျှာၚ်၊ အဝ်တာၚ်ခယျ။ — ရှ်ဗတဝ်သာဲ၊ ဟေန်ဆာဲသောတ။” (လိက်ဝိဓူရ) =“ကရဝိက်နှင့်ဥသြတို့သည် သံပြိုၚ်နှော၍ တစ်သံတည်းဖြစ်ကာ ပျော်မြူးစွာကျူးရင့်ကြသည်မှာပျားသကာအရသာကဲ့သို့ နားသောတအာရုံကို သာယာစေကုန်၏။” || ‘ဟေန်စဝ်’ (ကြိ) နှင့် အဓိပ္ပါယ်အတူတူ။')
,(15576,3,6,'ကို။ သို့။ အား။','(ပါဠိအနက်ပြန်ရာတွင်သုံးသည်)။')
,(15577,3,4,'စားသည်။','“သၟိၚ်ဨကရာတ်ဂှ်လေဝ် လောဟ်ကဵုသူရာ လောဟ်ကဵုဖျုန် ယာံဟွံဂွံဖျုန်တုဲ ဟွံဟာပ်ပုၚ်ရ။” (ဇ—၂၂ဝ။ အစွောံ) = “ဘုရင်သည်လည်း သေရည်အရက်ကို အလွန်နှစ်သက်၏၊ အသားကို အလွန်နှစ်သက်၏၊ အသားနှင့်ကင်း၍ ထမင်းမစား။” || “သၟိၚ်ဟာပ်ပုၚ်ဂယးတုဲ—။” (ဇ—၃၉ဝ။ အစွောံ။) = “မင်းသည် မနက်ထမင်းစားပြီးနောက်—။”')
,(15578,3,1,'သေတ္တာ။ တလား။ (?)','“ဟိပ်နွံဒၟံၚ်မွဲ၊ အဲစံရံၚ်ကၠာ။ အပ္ဍဲဟိပ်ဂှ်၊ ဗဒှ်သာ်လွာ။ လကိုဟ်စှ်ရ၊ ကၠနွံစှ်ၜါ။” (လိက်ဇိဝှစက္က) = “သေတ္တာတစ်ခုရှိသည်ကို ငါစုံစမ်းကြည့်မည်၊ ထို သေတ္တာထဲ­ ဘီလူးဆယ်ယောက်နှင့် ကျားတစ်ဆယ့်နှစ်ကောင်ရှိ၏။” || “ဟိပ်နွံမွဲအဵု၊ အဲပြၚ်ကဵုဏာ။ ဗစိုပ်တဲပ္ညဳ။ သာမဏဳကၠာ။ တုဲကေတ်နၚ်အဵု၊ ဒုၚ်ကဵုတလာ။” (လိက်ဇိဝှစက္က) (ဟိပ် =တလာ) || “သီုကဵုဟိပ်ဗိုန်၊ ပ္တိုန်ပၞးယိုက်ဏာ။” (လိက်ဇိဝှစက္က) = “သေတ္တာကို မြဲစွာပခုံးထက်တၚ်၍ သယ်ယူသွား၏။”')
,(15579,3,4,'စုအုံသည်။ ဝိုင်းအုံသည်။','“ကၞုဟ်ဒတုံစှ်ေ ပ္ဍဲဒေါဝ်ပုရိသာတ်ဂမၠိုၚ်တုဲ ခဍအ်ကၞုဟ်ဂှ်ပြောပ်အာတုဲ ညးဂမၠိုၚ်ဟုပ်ကၠုၚ်ဗဵု ကၠံၚ်မံၚ်အိုတ်ရ။” (ဇ—၂၁၅။ အစွောံ။) = “ထိုလိပ်သည်ကောင်းကင်ပြင်မှကျ၍ လိပ်ခွံသည်ကွဲ၏။ လူများဝိုင်းအုံလာ၍ ကြည့်ကြကုန်ရာ ဆူညံလျက်ရှိ၏။” || “ကဝွံစိုပ်သ္ၚိဗက် — ညးမဒဒှ်ေတံဂှ် ဍေံဟုပ်ကၠုၚ်အိုတ်ရ” တမ္ၚာဂှ်ချပ်။ (ဇ—၁၃၉။ အစွောံ။) = “ဤငါးသည် အိမ်သို့ရောက်သည်နှင့် ခင်မင်ရင်းနှီးကုန်သောသူတို့သည် စုအုံလာကြကုန်လတ္တံ့” ဟုတံငါသည်ကြံ၏။ || “တ္ၚေက်သ္ကံဂမၠိုၚ် ဗိုၚ်ဟုပ်စသြောံဂှ်—။” (ဇ—၄၈၄။ အစွောံ။) = “ကျေးများအုပ်စုသည် ထိုစပါးကို ဝိုင်းအုံစားကြကုန်၏။” || “ဇွကၠဵုသမ်အုဲဂှ် ရုဲဟုပ်ကၠံၚ်ဒၟံၚ်ရ။” = “ခွေးသေပုပ်ကောင်ကို ယင်ကောင်များစုအုံ၍ ဆူညံနေသည်။” || “မၞိဟ်ယဲဂှ် ပလက်ဟုပ်ဒၟံၚ်ရ။” = “လူနာသည် ချွေးတလုံးလုံးထွက်လျက်ရှိ၏။”')
,(15580,3,5,'အရှက်ကင်းမဲ့စွာ။ စုတ်စုတ်ပြတ်ပြတ်။ (?)','“မၞိဟ်ခလာတ်က္ဍိုပ်၊ ဟိုပ်ဟိုပ်အာတ်စ။” (လိက်မ္ၚဵုပိစှ်ောဒစာံ။ မာံထဝ်စိုပ်။) = “ဦးပြည်းခေါင်းတုံးသည် အရှက်ကင်းမဲ့စွာတောင်းရမ်းစား၏။”')
,(15581,3,4,'၁။ (ရေ) ချိုးသည်။','ဟုံဍာ် = ရေချိုးသည်။ || “ဍာ်ကမၠိုၚ်ဝွံ ကဵုအဲဂွံဟုံညိ။” (ဇ—၄၁၉။ အစွောံ။) = “ဤရေတွင်းရေကို ငါချိုးပါရစေ။”')
,(15581,3,4,'၂။ (အမွှေးနံ့သာ) လိမ်းကျံသည်။','ဟုံဂစေအ်၊ ဟုံဗော်မြမောဝ် = အမွှေးနံ့သာလိမ်းသည်။ || “(သၟတ်ဗြဴသုန္ဓရဳဂှ်) ဂြးသော်ဟုမ်စၠန်စရှ်ပ္ကဴတုဲ—။” (ဇ—၂၈၅။ အစွောံ။) = “အမျိုးသမီးငယ်သုန္ဒရီသည် ခေါင်းဖြီး၊ နံ့သာလိမ်း၊ပန်းပန်ပြီးလျှင်—။”')
,(15581,3,4,'၃။ ဆုံးရှုံးသည်။','“(ညးဍုၚ်တံဂှ် ကိစ္စသရၚ်မတန်ပ္တုဲပြဟ်ဂှ် ဟွံဂွံပ္တုဲတုဲ) ဟိုတ်မာဲဇလိၚ်ကၠေံကာလ ဟုံအာသီုသ္ၚောံရ။” (ဇ—၄၉။ အစွောံ။) = “ထိုမြို့သားတို့သည်လျင်စွာပြုအပ်သောအမှုကိစ္စကို မပြုဘဲလျှင် တွေဝေမေ့လျော့၍ အချိန်ရွှေ့ဆိုင်းသဖြင့် နောင်တပူပန်ခြင်းနှင့်အတူ ဆုံးရှုံးရ၏။” || “—၊ ကၠဵုဂွံဏာဖျုန်အဒေါဝ်ဂှ်တုဲ ပိုဲညးၜါဟုံထောံသၟးရ” ဖေအ်ၜါဂး။ (ဇ—၄ဝဝ။ အစွောံ။) = “မြေခွေးက ငါးအလယ်သားကို ရယူသွားသဖြင့် ငါတို့နှစ်ဦးသည် သက်သက်ဆုံးရှုံးရ၏” ဟုနှစ်ခုသောဖျံတို့ဆို၏။ || “အဲသ္အာရောၚ် အဲမြာ၊ အဲဒၟံၚ်ဂှ် ဟုံရအဴ။” (ဇ—ဝေသန္တဝ်။ အစွောံ။) = “ငါသွားလျှင်သာ ငါမြတ်လိမ့်မည်။ ငါနေသော်ကား ငါရှုံးလိမ့်မည်။”')
,(15582,3,4,'အကြံမအောင်ဖြစ်သည်။ အကြံအစည်ပျက်သည်။','“(လဗၚ်သမုၚ်တံ ချပ်ပၠံၚ်ၜးကေတ်ဂ္ညိဂ္ညာတ်သေဋ္ဌဳဂှ် သေဋ္ဌဳလၞိန်ဗပိန်ကၠေံတုဲ လဗၚ်တံဂှ်) ဟုံဂသပ်ဒးစိုပ်လၞီသ္ၚောံဟေၚ်။” (ဇ—၅၃။ အစွောံ။) = “သေသောက်ကြူးတို့သည် သူဋ္ဌေး၏လက်ဝတ်တန်ဆာတို့ကို လုယက်ရန်ကြံစည်သည်ကို သူဋ္ဌေးက နှိမ်နင်းအနိုင်ယူလိုက်သဖြင့် သေသောက်ကြူးတို့သည် အကြံအစည်ပျက်၍ ပူပန်သောကဖြစ်ကြရကုန်၏။”')
,(15583,3,4,'ဆုံးရှုံးသည်။','“ညးပဗၞိက် ကျဗၞိက်တုဲ ဒြပ်ညးဟုံလေၚ် (ဟုံဗြံ) အာအိုတ်ရ။”= “သူကုန်အရောင်းအဝယ်လုပ်ရာ ကုန်ရှုံး၍ သူ့ဥစ္စာဆုံးရှုံးကုန်သည်။”')
,(15584,3,4,'‘သ္ၚောံမှာ’ ရှု။','“လၟုဟ်ကောန်စိ၊ ဗျာဓိဒုက္ခာ။ ပိုဲမိမၜါ၊ ဟုံမှာရကောန်။” (လိက်မၚ်ဗၠာဲဟောံလွဳ)')
,(15585,3,4,'လုံ့လအကျိုးကို မခံစားရဖြစ်သည်။ လုံ့လပြုရကျိုးမနပ်ဖြစ်သည်။','“အဲမွဲဂှ် ပတဴလွဳပရာတံဇိုၚ်ကျာ် လုကဴၜါဣသုန်သၞာံတုဲတြ။ အဲဟွံဂွံဒှ်အရှန်ဏီ၊ ဆသောတာပန်ကီု အဲမဂွံဒှ်။ ကျာ်တြဲတုန်လေဝ် ပကၠေံပရိနိဗ္ဗာန်တုဲရ။ အဲမဟုံလွဳရ” ထေရ်အနန်ဂး။ (ဇ—၃ဝ၇။ အစွောံ။) =“ငါသည်ကား မြတ်စွာဘုရားခြေတော်ရင်း­ လုံ့လပြုနေသည်မှာ နှစ်ဆယ့်ငါးနှစ်ရှိလေပြီ။ ငါသည် ရဟန္တာမဖြစ်သေး၊ သောတာပန်မျှသာဖြစ်၏။ မြတ်စွာဘုရားသည်လည်း ပရိနိဗ္ဗာန်ပြုလေပြီ။ ငါသည် လုံ့လပြုရကျိုးမနပ်ဖြစ်ရလေပြီ” ဟုအရှင်အာနန္ဒာဆို၏။ || “ယွံအနန်၊ ယြဴပူဂဵုမွဲ နွံလွဳပ္ဍဲဓဝ်ကုသဵုတုဲဂှ် သဘဴမဒးဟုမ်အာလွဳဂှ် ဟွံမွဲရအနန်” ကျာ်တြဲဂး။ (ဇ—၃ဝ၇။ အစွောံ။) =“အာနန္ဒာ၊ ကုသိုလ်တရား­ လုံ့လရှိသောသူသည်ကား လုံ့လပြုရကျိုးမနပ်ဟူ၍မရှိ။” || “မိမဒးသာဲ၊ ကၟာဲနူၜတ်ၜတ်။ တ္ၚဲဝွံဟုံလွဳ၊ ရကျာ်သြဳဍောတ်။” (လိက်ရာဇာဟတ္ထိ) = “နုနယ်ငယ်ရွယ်စဉ်ကတည်းက မယ့်မှာ မုဆိုးမဖြစ်ရ၏။ အို—မယ့်ကျက်သရေမောင်၊ ဤယနေ့­ လုံ့လပြုရကျိုးမနပ်ဖြစ်ခဲ့လေပြီတကား။” || “ဖဍောၚ်ကာယ၊ ပလွဳဟုံလွဳ။” (လိက်ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “ကိုယ်အပင်ပန်းခံလုံ့လပြု၍ လုံ့လပြုရကျိုးမနပ်။”')
,(15586,3,4,'သီးချိန်ပွင့်ချိန်ကုန်ဆုံးသည်။ တုံးသည်။','‘အခိၚ်ကာလဏအ် ကြုက်ဟောံအာတုဲရ။’ = ‘ဤအချိန်ကာလတွင် သရက်သီးတုံးသွားပြီ။’')
,(15587,3,4,'ဝမ်းနည်းပူဆွေးသည်။ ကိုယ်နွမ်းစိတ်ပန်းဖြစ်သည်။ နှလုံးမသာမယာဖြစ်သည်။','“(သၟိၚ်ဟွံသ္ပဂရုကဵုဂၞကျာ်ဇၞော်တုဲ) ဂၞကျာ်ဇၞော်ဂှ် က္တဵုဒှ်ဝိပ္ပတိသာရဳ သေၚာံဟောံဇြ—။” (ဇ—၅၁၉။ အစွောံ။) = “မိဖုရားကြီးကို မင်းသည်ဂရုမစိုက်၍ မိဖုရားကြီးသည် နှလုံးမသာယာခြင်းဖြစ်၍ စိုးရိမ်ပူဆွေးဝမ်းနည်း၏။” || “သရာဲဗိုလ်လဗးပိုဲဍိက် ဟောံဇြသန်၊ — ပိုဲဍိက်ဗျူဗိုလ်လဗး ကဵုနွံဒြဟတ်ညိကၠာတုဲ—။” (အကြီုရာဇာဓိရာဇ်) = “ကျွန်တော်မျိုးတို့ရဲမက်ဗိုလ်ပါများသည် ကိုယ်နွမ်းစိတ်ပန်းနေကုန်ပြီ။ ရဲမက်ဗိုလ်ပါများကို ကျွန်တော်မျိုးတို့ အနားပေး၍ အင်အားရှိလာပါစေဦး။” || “ဗန်တဲဒေၚ်ဗျောံ၊ ဒှ်တဴဟောံဇြ။” (လိက်ဗောဓိသတ်စှ်။ ပဏ္ဍိတ။) =“လက်ပိုက်ကြံမှိုင်လျက် နှလုံးမသာမယာဖြစ်၏။”')
,(15588,3,4,'ငြိမ်းပျောက်သည်။ ချုပ်ငြိမ်းသည်။','“လၞီစံၚ်တူဟောံပၠိုတ်အာ။” = “ပူပန်သောကငြိမ်းပျောက်သည်။”')
,(15589,3,4,'ပြီးဆုံးသည်။ ကုန်ဆုံးသည်။ ကုန်လွန်သည်။','“ကာလသဘၚ်ပၞာန်ဟောံဟဲ တၠညးဗၞုဟ်စိုပ်ဂၞကျာ်—။” (အကြီုရာဇာဓိရာဇ်) = “စစ်ပွဲကာလကုန်လွန်ပြီးဆုံး၍ ဘုရင်က မိဖုရားကို အောက်မေ့လတ်သော်—။” || “နာဲညးတၠစိၚ်ဗ္တာၚ် စသိုၚ်တသိုက်မနုဿဘုံ ဟောံဟဲဖဲလဲတုဲ လသာစွံလဝ်တသိုက် က္ဍိုၚ်ဗ္တာၚ်ဍုၚ်ဟံသာဝတဳ ကလိဘဴစဴစသိုၚ် တသိုက်ဒေဝတဴ—။” (အကြီုရာဇာဓိရာဇ်) = “ဆင်ဖြူရှင်ဗညားဦးမင်းသည် လူ့ဘုံစည်းစိမ်ကိုခံစား၍ ဝလင်ကုန်ဆုံးပြီးနောက် ဟံသာဝတီထီးနန်းစည်းစိမ်ကို စွန့်ခွာကာ တမလွန်သို့လား၍ နတ်စည်းစိမ်ကို ခံစားပြန်၏။” || “လဗိုတ်ကျာပြဲ၊ ကဵုဟောံဟဲအာ။” (လိက်ဇိဝှစက္က) = “လေမုန်တိုင်းသည် ရပ်စဲကုန်ဆုံးသွားပါစေသတည်း။” || “လောံလာဲဒေၚ်ဗျောံ၊ ဟွံတီဟောံဟဲ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ပူဆွေးကြံမှိုင်ရခြင်းသည် မကုန်ဆုံးနိုင်ပါပြီတကား။” || ‘ဟဲဟောံ’ (ကြိ) နှင့်အတူတူ။')
,(15590,3,4,'ပြောသည်။ ပြောဆိုသည်။',NULL)
,(15591,3,4,'အဆုံးတိုၚ်စကားကို ပြောဆိုသည်။ (ပါဠိ—ပရိယန္တဘာဏဳ)',NULL)
,(15592,3,4,'စကားတုံ့လှယ်ပြောဆိုသည်။',NULL)
,(15593,3,4,'အတင်းအဖျင်းစကားကို ပြောဆိုသည်။',NULL)
,(15594,3,4,'မင်္ဂလာရှိသောစကားကိုပြောဆိုသည်။',NULL)
,(15595,3,4,'မာကျောသောစကားကို ပြောဆိုသည်။',NULL)
,(15596,3,4,'ကောင်းသောစကားကို ပြောဆိုသည်။',NULL)
,(15597,3,4,'နှုတ်ခွန်းဆက်စကားပြောဆိုသည်။',NULL)
,(15598,3,4,'ချစ်ရေးဆိုသည်။ အိမ်ထောင်ရေးစကားပြောဆိုသည်။',NULL)
,(15599,3,4,'ထပ်ခါတလဲလဲပြောသည်။',NULL)
,(15600,3,4,'ပြောပြသည်။ အသိပေးသည်။','“ဗမၞးထေဲသလံၚ်စဴအာရ။ ဒဒှ်ဂှ်ညးအာဟီုကလောဟ်ကဵုဗမၞိဟ်ရ။” (ဇ—၁၉၁။ အစွောံ။) = “ဒေါသမီးတဟုန်းဟုန်းတောက်လောင်လျက် ပုဏ္ဏားပြန်လာကြောင်းကို သူတစ်ပါးတို့သည် ပုဏ္ဏေးမအား သွားရောက်ပြောပြ၏။”')
,(15601,3,4,'ကျယ်လောင်စွာ အဆက်မပြတ်ပြောသည်။','“(ပြောဟိတ်အရေဝ်ဂၠိုၚ်ဂှ် ယာံဟီုတိုန်ဗက်) အခေါၚ်ညးသ္အာၚ် မသ္ဂောံဟီုဟွံမွဲရ။ ဆဇကုမွဲကီု ဟီုကမြေံတဴ။” (ဇ=၁ဝ၇။အစွောံ။) = “ထိုစကားများသောပုရောဟိတ်က စကားပြောဆိုသည်နှင့် အခြားသူများပြောခွင့်မရှိတော့။ မိမိတစ်ဦးတည်းသာလျှင် ကျယ်လောင်စွာ အဆက်မပြတ်ပြော၏။” || ‘ဟီုဂမြံ’ နှင့်အတူတူ။')
,(15602,3,4,'တုံ့ပြန်ပြောဆိုသည်။ ချေပပြောဆိုသည်။',NULL)
,(15603,3,4,'အပျော်သဘော နောက်ပြောင်ကျီစယ်ပြောဆိုသည်။','‘ဂရိုၚ်ပွေၚ်’ တွင်ရှု။')
,(15604,3,4,'ပြောဆိုကဲ့ရဲ့သည်။',NULL)
,(15605,3,4,'အိမ်ထောင်ရေးစကားပြောသည်။ ရည်းစားစကားပြောသည်။ ချစ်ရေးဆိုသည်။','“(မဂှ်) သၟိက်စံၜတ်ကောန်ဗြဴတေံဂှ် ညံၚ်မနိဿဲကဵုကိလေသကီု ဟီုဂလာန်သ္ၚိကၟိန်တုဲသ္ဂန်ကအ်တဲကောန်ဗြဴရ။” (ဇ—၁ဝ၂။ အစွောံ။) = “ဖခင်သည် သမီးကိုစုံစမ်းလိုသဖြင့် ကိလေသာကို မှီသကဲ့သို့ပြုကာ သမီးကိုချစ်ရေးဆို၍ သမီးကိုလက်­ဆွဲ၏။”')
,(15606,3,4,'ပြောဆိုသည်။',NULL)
,(15607,3,4,'အဆက်မပြတ် ကျယ်လောင်စွာပြောသည်။','“(ပြောဟိတ်အရေဝ်ဂၠိုၚ်ဂှ်) မိၚ်ဂလာန်သၟိၚ်ဗက် သမးအလိုန်မဒွံကျာဇမ်ကာတ်ကီု ဟီုဂမြံတိုန်ဂလာန်ထပ်ထပ်ရ။” (ဇ—၁ဝ၇။အစွောံ။) = “စကားများသောပုရောဟိတ်သည် ဘုရင့်စကားကိုကြားသည်နှင့် လေပြင်းထိသောလှိုင်းတံပိုးကဲ့သို့ ကျယ်လောင်သောအသံဖြင့် စကားအထပ်ထပ်ပြောလေ၏။”')
,(15608,3,4,'‘ဟီုဂရိုၚ်ပွေၚ်’ (ကြိ) နှင့်အတူတူ။',NULL)
,(15609,3,4,'၁။ အတင်းပြောသည်။','“ဟိုတ်နူဍေံသုၚ်အရက်လောန် အိက်အရက်ဂးတုဲ ညးဂမၠိုၚ်ဟီုစတဴအိုတ်ရ။” = “သူအရက်သောက်လွန်းသဖြင့် အရက်သမားဟုဆိုကာ လူတကာတို့ အတင်းပြောကြကုန်၏။”')
,(15609,3,4,'၂။ ပြောပြသည်။ အသိပေးသည်။','“(သၟိၚ်မြာ်ထဝ်) မပဒတဴပ္ဍဲက္ဍိုပ်တၟံသြန်ဂှ် (လၟဂှ်) ဍေံညာတ်တုဲ ဍေံကလေၚ်စဴ ဍေံဟီုစကုကောန်တြုံဍေံမွဲမဂွံတီ။” (ဇ—၁၅၉။ အစွောံ။) =“ငွေတောင်ထိပ်­နေသော ရွှေဥဒေါင်းမင်းကို မုဆိုးမြင်ပြီးလျှင်အိမ်ပြန်၍ တစ်ယောက်သောသားအားပြောပြ၍ ထိုသားတစ်ယောက်သာလျှင် သိရ၏။” || “ပြောဟိတ်စဴစိုပ်ပြာသာဒ်သ္ၚိဇကုတုဲ (ဒဒှ်ဂှ်) ဟီုစကဵုသမ္ဘာရ။” (ဇ—၁၉၁။ အစွောံ။) = “ပုရောဟိတ်သည် မိမိ၏ပြာသာဒ်အိမ်သို့ ပြန်ရောက်သောအခါ ထိုအဖြစ်ကို ဇနီးသည်အား ပြောပြ၏။”')
,(15610,3,4,'ပြက်ရယ်ပြုသည်။ ရယ်သွမ်းသွေးသည်။','‘ဂရိုၚ်စရဵု’ တွင်ရှု။')
,(15611,3,4,'မဂ်ဖိုလ်မရဘဲလျက် ဈာန်မရဘဲလျက် မဂ်ဖိုလ်ရသည် ဈာန်ရသည်ဟု ဟန်ဆောင်ဝင့်ကြွားသည်။','“သွဟ်ဝွံ မဟီုစဇျာန်မက်ဂွံဗၠးဟေၚ်။” (သ္ကေံမိလိန္ဒဝတ္ထု) = “ဤဖြေဆိုချက်သည် ဈာန်မဂ်ဖိုလ်ရကြောင်း ဟန်ဆောင်ဝင့်ကြွားခြင်းမှလွတ်၏။” || ‘ပ္တိုန်စဇျာန်မက်ဖဵု’ (ကြိ) နှင့်အတူတူ။')
,(15612,3,4,'ပြက်ရယ်ပြုသည်။','“ဗောဓိသတ်ဖရာပ် ဟီုစရဵုကဵုခ္ဍာ်။” (ဇ—၂၇၄။ အစွောံ။) =“ဘုရားလောင်းခိုသည် ကျီးကို ပြက်ရယ်ပြု၏။”')
,(15613,3,4,'နားမခံသာအောင် ရုန့်ရင်းကြမ်းတမ်းစွာပြောဆိုသည်။','“ပူဂဵုမဟီုစုတ်ဒွဵုကတောဝ်ကဵုဗောဓိသတ်။” (သၠပတ်ဒ္ၚောဝ်သၜေံါ) = “ဘုရားလောင်းအား နားမခံသာအောင်ရုန့်ရင်းကြမ်းတမ်းစွာ ပြောဆိုသောသူ။”')
,(15614,3,4,'ပြောဆိုခြိမ်းခြောက်သည်။',NULL)
,(15615,3,4,'ရမ်းသန်းပြောသည်။','“ကသပ်တၠညးဒှ်တုဲ ဟီုဆစုတ်ရောၚ်အဴ။” (ဇ—၃၇၃။ အစွောံ။) = “မင်းကြီးသည် စိတ်ကူးပေါက်ရာ ရမ်းသန်းပြောခြင်းသာဖြစ်၏။”')
,(15616,3,4,'လူတွင်ကျယ်လုပ်၍ ဝင်ပြောသည်။ ဝၚ်ပြောစွက်ဖက်သည်။','“ဟွံဆေၚ်က္ဍိုပ်ဗှ်ေ၊ဗှ်ေကၠုၚ်ဟီုဆာ။ မူဆေၚ်က္ဍိုပ်ဗှ်ေ၊ ဗှ်ေကၠုၚ်ဟီုတာ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “နၚ်နှင့်မဆိုင်နင့်အပူမဟုတ်ဘဲ နၚ်လာ၍ဝၚ်စွက်ပြောဆို၏၊ နင့်သောက်ပူမပါဘဲ နၚ်လာ၍ပြောဆိုတားမြစ်နေ၏။”')
,(15617,3,4,'ပြောဆိုသည်။ မှာကြားသည်။','“သၟိၚ်ပလံၚ်ဏာဣသိ (ပ္ဍဲဥဒျာန်တေံတုဲ) ခၞံအဿမာပိုတ်တုဲ ဋ္ဌာန်ဗ္တံကီု ဋ္ဌာန်တ္ၚဲကီု ခၞံဗဒှ်ကဵုတုဲ — ဟီုဇီုလဝ်ကဵုပၟၚ်ဥဒျာန်တုဲ သၟိၚ်စဴအာဍုၚ်ရ။” ဇ—၁၄၉။ အစွောံ။ = “မင်းသည် ရသေ့ကို ဥယျာဉ်သို့ ပင့်ဆောင်သွားပြီး ကျောင်းသင်္ခမ်းဆောက်၍ ညဉ့်သန့်ရာအရပ် နေ့သန့်ရာအရပ်တို့ကို ဆောက်လုပ်ပေးပြီးလျှင် ဥယျာဉ်စောင့်အား ပြောဆိုမှာကြား၍ မင်းသည်မြို့သို့ဝၚ်၏။” || “(အမာတ်ဂှ်) လ္ၚောဝ်ကျာ်တုဲ ဂလာန်ပၠန်ဂတးသံၚ်ဝါသဟီုဇီုကေုာံကျာ်တြဲ။” (ဇ—၂၈၂။ အစွောံ။) = “ထိုအမတ်သည် မြတ်စွာဘုရားကိုရှိခိုး၍ မြတ်စွာဘုရားနှင့်တကွ ပဋိသန္ထာရစကားကို ပြောဆို၏။” || “အမာတ်ဟီုဇီုဗ္တောန်ဖျောန် သီုသၟိၚ်သီုညးဂၟံၚ်လ္ၚီဂှ်ရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “အမတ်သည် မင်းနှင့်တကွ သူရဲတစ်ထောင်တို့ကို ပြောဆိုသင်ကြားမှာကြား၏။” || “ဂုန်မိဟီုဇီုရိုဟ်အာ ဟွံတီအိုတ်ရ။” (ဇ—၅၃၂။ အစွောံ။) = “အမိကျေးဇူးကို ပြောဆိုရေတွက်၍ မကုန်နိုင်ပါ။” || “အဲပသၟိၚ်ဂှ် သတ္တံကတဴကီု တၜိုဟ်ကီု ဍေံဟီုဇီုအဲဂွံမိၚ်ညိ” သၟိၚ်ချပ်။ (ဇ—၂၈၉။ အစွောံ။) = “ငါမင်းပြုသည်မှာ လူအပေါင်းတို့ ပူကုန်သလော အေးချမ်းကုန်သလော ၄င်းတို့ပြောဆိုကြသည်ကို ငါကြားလို၏” ဟုမင်းသည်ကြံ၏။ || “သီုညးပန်ဂှ် ဟီုဇီုကေုာံရၚ်သ္ကံတုဲ က္တဵုစဴအာရ။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “လေးယောက်သောသူတို့သည် အချင်းချင်းပြောဆိုကုန်ပြီးလျှင် ထပြန်သွားကြကုန်၏။”')
,(15618,3,4,'ပြောဆိုအသိပေးသည်။','“ပိုဲဟွံဟီုတလိုဟ် လ္ပဗတိုက်ဏီ။” (အကြီုရာဇာဓိရာဇ်) = “တိုက်ရန်ငါတို့မပြောဆို အသိမပေးသေးလျှင် မတိုက်ပါလေနှင့်ဦး။” || ‘ဟီုကလိုဟ်’နှင့်အတူတူ။')
,(15619,3,4,'ဟောပြောသည်။ ရှင်းဆိုပြောပြသည်။','“အတိုၚ်က္တဵုဒဒှ်အိုဿီုဂှ် သေဋ္ဌဳဗြဴဟီုတွံကဵုရ။” (ဇ—၁၄။ အစွောံ။) = “သူဋ္ဌေးမသည် အလုံးစုံသောအဖြစ်အပျက်ကို ရှင်းဆိုပြောပြ၏။” || သဘၚ်ဟီုတွံလိက်ပတ်မန် = မွန်စာပေဟောပြောပွဲ။')
,(15620,3,4,'ချိုးနှိမ်၍ပြောသည်။ ရှက်အောင်ပြောသည်။','“ယွံနန္ဒ၊ — ပဟိုတ်ကဵုမဂွံဗြဴတုဲရောၚ် မဂွံပၟဝ်ဓဝ်ခမဳရောၚ်မ္ဂးဂှ် ဍေံဟွံဆာဲညိသွံနန္ဒ” တိပိုန်သာရိပိုတ်ဂး ဟီုထဍိုက်ကၠေံနန္ဒရ။ (ဇ—၁၈၂။ အစွောံ။) = “နန္ဒ၊ မိန်းမ၊ရလိုခြင်းကြောင့် ရဟန်းတရားကို အားထုတ်သည်ဆိုသည်မှာ မဖြစ်ကောင်းပါလားနန္ဒ” ဟုရှင်သာရိပုတ္တရာဆိုကာ နန္ဒအား ရှက်စေရန်ပြော၏။')
,(15621,3,4,'ယောင်ယမ်းပြောဆိုသည်။ မြည်းတမ်းသည်။','“ညံၚ်ရဴလဗၚ်သူရာမသုၚ်ဗ္ၜူတုဲ ရဴမဟီုဒမာန်တဴရောၚ်သွံ။” (ဇ—၅၃၄။ အစွောံ။) = “အရက်သမားသည် အရက်သောက်မူးယစ်၍ပြောဆိုမြည်တမ်းသကဲ့သို့။” || ‘ဒမာန်’ (ကြိ) တွင်လည်းရှု။')
,(15622,3,4,'တိုးတိုးပြောသည်။','“ဟီုဒၟံၚ်ဒီုဒီု ဟွံကဵုညးမိၚ်ရ။” (ဇ—၅ဝ။ အစွောံ။) = “လူမကြားအောင် တိုးတိုးပြောနေ၏။”')
,(15623,3,4,'ပြောဆိုလမ်းညွှန်သည်။','“ဒၞာဲသ္ၚိညးနွံဂှ် ဟီုပ္ညုၚ်ကဵုအဲညိ။” = “သူ့အိမ်ရှိသည့်နေရာကို ကျွန်တော်အား လမ်းညွှန်ပေးပါ။” || “ပ္ဍဲက္ဍိုပ်တၟံသြန်တေံ မြာ်ထဝ်မွဲနွံ မအဲဟီုပ္ညုၚ်လဝ်အဴ”ကောန်လၟဂး။ (ဇ—၁၅၉။ အစွောံ။) = “ထိုငွေတောင်ထိပ်­ ရွှေဥဒေါင်းရှိကြောင်း အကျွန်ုပ်၏ဖခင် ပြောပြလမ်းညွှန်ထား၏” ဟုမုဆိုးသားဆို၏။')
,(15624,3,4,'စွပ်စွဲပြောဆိုသည်။ စော်ကားသည်။',NULL)
,(15625,3,4,'စွပ်စွဲပြောဆိုသည်။ ချိုးနှိမ်ပြောဆိုသည်။',NULL)
,(15626,3,4,'မိမိကိုယ်ကို မိမိဂုဏ်ဖော်သည်။ ကိုယ်ရည်သွေးသည်။ ကြွားဝါသည်။',NULL)
,(15627,3,4,'ပြောဆိုအပြစ်တင်သည်။',NULL)
,(15628,3,4,'ပြောဆိုအသိပေးသည်။ ကြားသိစေသည်။','“(ဒဒှ်ကောန်ဇကုဂှ်) ပြောဟိတ်ဟီုပ္တီသၟိၚ်ရ။” (ဇ—၄ဝ၁။ အစွောံ။) = “မိမိသား၏အဖြစ်ကို ပုရောဟိတ်သည် မင်းအား ပြောဆိုကြားသိစေ၏။”')
,(15629,3,4,'(စိတ်သောကခံစားနေရာမှ) စိတ်တည်ငြိမ်မှုရလာအောင် ဖျောင်းဖျပြောဆိုသည်။တရားချသည်။','“(ဂၞကျာ်ပကၠေံကာဂစိုတ်တုဲ သၟိၚ်စံၚ်တူယာံဒမာန်ဒၟံၚ်) ကလောဂမၠိုၚ် ဟီုပ္တေဝ်ကဵုကီုလေဝ် စိုတ်သၟိၚ်ဂှ် ဟွံသၟဟ်ရထ။” (ဇ—၂ဝ၇။ အစွောံ။) = “မိဖုယားသေလွန်၍ မင်းသည်ပူဆွေးငိုကြွေးနေရာ ဆွေမျိုးတို့က ပြောဆိုတရားချသော်လည်း မင်း၏စိတ်သည် (ပြောင်းလဲရန်) မတတ်နိုင်။” || ‘ပတေဝ်ကဵုစိုတ်’ (ကြိ) လည်းရှု။')
,(15630,3,4,'(ယုံကြည်လာအောင်၊ လက်ခံလာအောင်) ဖျောင်းဖျသည်။ နားချသည်။ အယုံသွင်းသည်။ သဘောပေါက်သိရှိစေသည်။','“(ကုကၞိဂှ်) ဗ္ဂဲမွဲသ္အာၚ်ရပ်ဂွံ ညံၚ်နဲကၠာတေံကီု ဟီုပ္တေဟ်ဗ္ဂဲမွဲတုဲ ကဵုဗလးကၠေံဇကုရ။” (ဇ—၁၃၇။ အစွောံ။) = “ထိုကြွက်ကို အခြားကြောင်တစ်ကောင်ကဖမ်းမိသည်ရှိသော် ထိုကြွက်သည် ယခင်နည်းအတိုင်း ထိုကြောင်အား ယုံအောင်ဖျောင်းဖျပြောဆိုပြီး မိမိအားလွှတ်စေ၏။” || ဗောဓိသတ်ညာတ်ဟိုတ်ဂစေံၜါဂှ်တုဲ “ပ္ဍဲကာလဝွံ အဲဟီုပတှ်ေကဵုစိုတ်မိအဲ သၟဟ်ရထရ” ချပ်တုဲ—။ (ဇ—၂၆၉။ အစွောံ။) = ဘုရားလောင်းသည် ထိုငှက်နှစ်ခုအကြောင်းကိုမြင်၍ “ယခုမယ်တော်ကို သဘောပေါက်သိရှိစေခြင်းငှာ တတ်ကောင်းပြီ”ဟုကြံ၍—။ || ‘ပ္တေဟ်ကဵုစိုတ်’ (ကြိ) လည်းရှု။')
,(15631,3,4,'အဖျက်သဘောပြောသည်။ ဖျက်လိုဖျက်ဆီးပြောသည်။ ကုန်းချောသည်။','“(ခမဳ) တၠဘာဂှ် အာကၠေံတုဲ ခမဳအာဂန္တုကဂှ် ဟီုပလီုဒကာတံဂှ်ရ။” (ဇ—၂၉၈။ အစွောံ။) = “ကျောင်းနေရဟန်းသွားသည်ရှိသော် အာဂန္တုကရဟန်းသည် ဒကာတို့ကို အဖျက်သဘောကုန်းချော၏။”')
,(15632,3,4,'ပြောကြားသည်။ အသိပေးသည်။ ပြောပြသည်။','“အတိုၚ်သၟိၚ်မဟီုဂှ် ဗောဓိသတ်ဟီုပၟိၚ်ဍေံရ။” (ဇ—၂၄၃။ အစွောံ။) = “ဘုရင်ပြောသည့်အတိုင်း ဘုရားလောင်းသည် သူ့ကိုပြောကြား၏။” || “ဒဒှ်ဂှ် (ရသိ) စဴဟီုပၟိၚ်ကဵုသမ္ၚေဟ် ဒကာဇကုဂှ်ရ။” (ဇ—ဝိဓုရ။ အစွောံ။) =“ထိုအကြောင်းကို ရသေ့သည် မိမိဒကာဖြစ်သောသူကြွယ်အား ပြန်၍ပြောဆိုအသိပေး၏။” || ‘ပၟိၚ်’ (ကြိ) လည်းရှု။')
,(15633,3,4,'ရှင်းပြသည်။ ရှင်းလင်းပြောဆိုသည်။','“ဍေံဟွံကၠးစိုတ်မ္ဂး ဟီုပျးကဵုဍေံညိ။” = “သူသဘောမပေါက်လျှင် သူ့ကိုပြောဆိုရှင်းပြပါ။”')
,(15634,3,4,'နှစ်ဦးနှစ်ဖက်အကြား ဝင်ရောက်ဖျန်ဖြေပြောဆိုသည်။','“ဇယျသုရ၊ဟီုပြာ်အကြာ။ မိတအ်ညးၜါ၊ ကၞပ်ညိကၠာရ။ သွေက်ဇဵုမ္ဂးဂှ်၊ က္တဵုဒှ်ဒေါသ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) = “ဇယျသုရသည် ထိုနှစ်ဦးနှစ်ဖက်အကြား ဝၚ်ပြောဆိုဖျန်ဖြေ၏၊ မယ်တို့နှစ်ဦးတိတ်ပါတော့၊ခိုက်ရန်မည်သည် ဒေါသဖြစ်စေ၏။” || “တုဲဟီုပြာ်ရ၊ ဝါဒညးၜါ။” (လိက်သၟိၚ်ဇဲယဒတ္တ) =“နှစ်ဦးအကြားဖြစ်သော အငြင်းအခုံကို ဖျန်ဖြေပြောဆို၏။”')
,(15635,3,4,'ပြဆိုသည်။ ထင်ရှားစေရန်ပြောသည်။','“နမဟီုပၠတၞောဝ်ဒတောဝ် မလောန်နူညးဂှ်လေဝ်ကီု—။” (ဇ—၃၆၈။ အစွောံ။) = “(သူတစ်ပါးတို့ထက်သာလွန်သော မိမိ၏) ဆွေမျိုးစဉ်ဆက်ကို ပြဆိုသဖြင့်လည်းကောင်း—။” (ညောင်ကန်)')
,(15636,3,4,'စကားတုံ့လှယ်ပြောဆိုသည်။','“အဲကော်သၟာန်ဍေံကီုလေဝ် ဍေံဟွံဟီုပၠန်ဂတးကဵုအဲရ။” = “သူ့ကိုငါခေါ်မေးသော်လည်း ငါ့ကို သူစကားတုံ့လှယ်မပြော။”')
,(15637,3,4,'အပြစ်ပြောသည်။ အတင်းအဖျင်းပြောသည်။',NULL)
,(15638,3,4,'ပြောပြသည်။','“(ရသိညာတ်ကေတ်ဍုၚ်နာ်တုဲ) စဴဟီုဗ္စကဵုဒကာဇကုရ။” (ဇ—ဝိဓုရ။အစွောံ။) = “ရသေ့သည် နဂါးပြည်ကိုမြင်ပြီးနောက် မိမိဒကာအား ပြန်၍ပြောပြ၏။”')
,(15639,3,4,'ပြောဆိုတိုက်တွန်းသည်။',NULL)
,(15640,3,4,'နှစ်ဦးအကြား ချစ်ခြင်းကိုဖျက်သည်။ ကုန်းချောသည်။','“အမာတ်ဂှ်သၟိၚ်ဇိုန်ကဵုပိုန်ဟာန်ယဿပတ် ဂၠိုၚ်သန်ရ။ ညးမွဲသ္အာၚ်ဂှ် စောန်စိုတ်ကဵုအမာတ်ဂှ်တုဲ ဍေံဟီုဗျဵုကဵုသၟိၚ်ရ။” (ဇ—၂၈၂။ အစွောံ။) = “ထိုအမတ်ကို မင်းသည် စည်းစိမ်ဥစ္စာများစွာ ပေး၏။ တစ်ပါးသောသူသည် ထိုအမတ်ကို မနာလိုသဝန်တို၍ မင်းအားကုန်းတိုက်၏။” || “ယွံမရှာတ်၊ အသဒိသကုမာ ကောတၠအဲဂှ် သၟိက်တသိုၚ်ကေတ် ကၟိန်ဍုၚ်တၠအဲပၠန်ယး” သာ်ဝွံ (အမာတ်ဂှ်) ဍေံဟီုဗျဵုအကြာရ။ (ဇ—၁၈၁။ အစွောံ။) = “အရှင်မင်းမြတ်၊ အရှင့်နောင်တော် အသဒိသကုမာသည်အရှင့်ထီးနန်းကို လုယူလိုပြန်သတတ်” ဟုထိုအမတ်သည် ကုန်းချော၏။')
,(15641,3,4,'လိမ်လည်သည်။ လှည့်စားသည်။',NULL)
,(15642,3,4,'လိမ်လည်လှည့်စားပြောဆိုသည်။',NULL)
,(15643,3,4,'ကြမ်းတမ်းစွာပြောသည်။ ပြောဆိုစော်ကားသည်။',NULL)
,(15644,3,4,'စကားပြောသည်။',NULL)
,(15645,3,9,'ရှေးရှုခေါ်ရာ­ သုံးသောစကား။ အို။ ဟယ်။','“ဟာဲတေမဳယျကုမ္မာဟိုဲ၊ ပေၚ်ကၠုၚ် (၅) သၞာံ ကဵုယာဲတုဲရသွံလေဝ်ကောန်။” (ဇ—တေမဳ။ အစွောံ။) = “အိုချစ်သားတေမိယကုမ္မာ၊မယ်မယ့်သားအသက် (၅) နှစ် ပြည့်ခဲ့လေပြီတကား။” || “ဟာဲမၞိဟ်ခါခဏဳ၊ ဗှ်ေစ္ဍးအာကၠေံနူဏအ် ပြဟ်ရ။” = “ဟယ်သူယုတ်မာ၊ ဤနေရာမှ နၚ်အမြန်ထွက်သွားစမ်းပါ။” || “ဟာဲဂဒိုအ်၊ ပလံၚ်နၚ်ဂၠုၚ်ညိ။” (ဇ—၃။ အစွောံ။) = “ဟယ်ကူးတို့သည်၊ လှေကိုပို့လာလှည့်လော့။”')
,(15646,3,11,'(ကြိ) ပျက်စီးသည်။ ဆုတ်ယုတ်သည်။ တွေဝေသည်။','(ပါဠိ—ဟာယန) || “ဥပးတံ လ္ပဟိုတ်မာဲဟာဲယနညိ။” (သြဝါဒဒဳပနဳ) = “သီတင်းသည်တို့၊ မမေ့လျော့မတွေဝေလေနှင့်။” || “ယဝ်ဍေံဟိုတ်မာဲ၊ ဍေံဟာဲယန။” (လိက်သုပိဏ္ဏကုမ္မာ။ မၚ်သၚ်ကြာ။)')
,(15647,3,4,'၁။ ပေါင်းဖက်သည်။ ပေါင်းဖော်သည်။ ပေါင်းသင်းသည်။','“လ္ပဟုဲကေုာံသမၠီု မှတ်ဒရီုကုတၠပညာညိ။” (ဇ—၇၉။ အစွောံ။) = “သူမိုက်နှင့်တကွ မပေါင်းဖော်ရာ။ ပညာရှိနှင့်တကွသာလျှင် မဖြစ်မနေပေါင်းဖော်ပါလေ။” || “မူပတၠအဲဟွံမိက်ဟုဲကေုာံပူဂဵုသမၠီုဂှ်ရော။” (ဇ—၄၈ဝ။အစွောံ။) = “အဘယ်ကြောင့် သင်သည် သူမိုက်နှင့်တကွ မပေါင်းဖော်လိုသနည်း။”')
,(15647,3,4,'၂။ (သင်္ချာ) ပေါင်းသည်။','“(၃) ဟုဲကဵု (၄) မ္ဂး ဂွံ (၇) ရ။” = “(၃) ကို (၄) နှင့်ပေါင်းလျှင် (၇) ရ၏။”')
,(15647,3,4,'၃။ ကျုံးယူသည်။','“သ္ၚုဂှ်ဟုဲစုတ်ပ္ဍဲနညိ။” = “ဆန်ကို တောင်းထဲသို့ ကျုံးထည့်ပါ။”')
,(15648,3,4,'၁။ ပေါင်းသင်းသည်။ ပေါင်းဖက်သည်။ ပေါင်းဖော်သည်။','“ယြဴပူဂဵုမွဲ မဒးသိပ်ဂၠိပ်ဟုဲနှဴ ဂကောံပူဂဵုသမၠီုမယုတ်မာဂှ်တုဲ တသိုက်မဗိုန်လအ်ဂှ် ဟွံကလိဂွံရ။” (ဇ—၃၉၇။ အစွောံ။) = “ယုတ်မာသောသူမိုက်နှင့်တကွ မှီဝဲပေါင်းဖော်သောသူသည် အရှည်တည်မြဲသော ချမ်းသာခြင်းကိုမရ။” || “ဂွံဟုဲဟာဲသိပ်ဂၠိပ် ကေုာံတၠပညာတုဲ ဒှ်မ္ၚဵုမပြဲရ။” (ဇ—၁၉ဝ။အစွောံ။) = “ပညာရှိနှင့်တကွ ပေါင်းဖော်မှီဝဲရခြင်းသည် မြတ်သောမင်္ဂလာတည်း။” || “ကေုာံဇန်ဒမိက် ဟွံဂြၚ်ဂုန်ညး မပ္တုဲလဝ်ပ္ဍဲဇကုဂှ် မဒးဟုဲဟာဲဂှ် ဟွံပြဲသက်က်ဟေၚ်။” (ဇ—၁၇၄။ အစွောံ။) = “မိမိအားပြုထားသောကျေးဇူးကို မသိတတ်သော သူယုတ်မာနှင့်တကွ ပေါင်းဖော်ရ ခြင်းသည် မမြတ်သည်သာလျှင်တည်း။” || “ပူဂဵုဟွံဂပ်ဂဝ်ဟုဲဟာဲဒက်မိတ် စှ်ၜါသာ်။” (သၠပတ်စှ်ၜါရာသဳ) = “ပေါင်းဖော်မိတ်ဖွဲ့ခြင်း မပြုအပ်သောပုဂ္ဂိုလ် (၁၂) မျိုး။”')
,(15648,3,4,'၂။ မေထုန်မှီဝဲသည်။ကာမစပ်ရှက်သည်။ လိၚ်ဆက်ဆံသည်။','“ပွမဟုဲဟာဲဓဝ်မေထုန် ကေုာံညးမဟွံသေၚ်ကဵုပွံၚ်ဇကုဂှ်တၠပညာတံဟွံထိုၚ်သးရ။” = “မိမိ၏အိမ်ထောင်ဘက်မဟုတ်သောသူနှင့်တကွ ကာမစပ်ရှက်ခြင်းကို ပညာရှိတို့မချီးမွမ်းကုန်။”')
,(15648,3,3,'ရောနှောသော။ အရောဖြစ်သော။ ပြွမ်းသော။','ဂြိုပ်ဆုမဟုဲဟာဲ (ဇ—၅၁၄။ အစွောံ။) = သစ်ပင်အမျိုးမျိုး ရောနှောပေါက်ရောက်သောတော။ ပြွမ်းသောသစ်တော။')
,(15649,3,4,'အပေါင်းအသင်းမှားသည်။ လူပေါင်းမှားသည်။','“ဟုဲလုတ်လေၚ်ဒိုက်၊ ဟုဲဒးသိုက်အာ။” (လိက်ဓနဥ္ဇယျကုမ္မာ။ အစွောံ။) = “အပေါင်းအသင်းမှားသဖြင့် ပျက်စီးဆုံးရှုံး၍ အပေါင်းအသင်းမှန်က ချမ်းသာသွား၏။”')
,(15650,3,1,'လျှို့ဝှက်ချက်။ လျှို့ဝှက်အပ်သောကိစ္စ။ ကိုယ်ရေးကိုယ်တာကိစ္စ။ အတွင်းရေးကိစ္စ။','“ဟုဲဟှ်ဝွံ ပသာ်ဗၟာမဂွံတီအာရော” တၠညးရာဇာဓိရာဇ်သၟာန်။ (အကြီုရာဇာဓိရာဇ်) = “ဤလျှို့ဝှက်ချက်ကို ဗမာတို့ဘယ်လိုသိသွားကြသနည်း” ဟုဘုရင်ရာဇာဓိရာဇ်မေး၏။ || “ယွံမိ၊ သဘဴဗြဴကဵုဗြဴတံဂှ် ဟုဲဟဟ်ဇကုဂှ် ဟွံဂြပ်ဗ္ဒန်ရ။” (ဇ—၄၁၁။ အစွောံ။) = “မိခင်၊ မိန်းမတို့မည်သည် မိန်းမသားချင်း လျှို့ဝှက်အပ်သောအမှုတို့ကို မလျှို့ဝှက်ကုန်။” || “ဟုဲဟဟ်ဇကုဂှ်မူရဴညးမွဲ ဂပ်ဂဝ်ဖျိုန်လဝ်ရော။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “မိမိ၏လျှို့ဝှက်အပ်သောကိစ္စကို အဘယ်သူ့ကို ပြောပြအပ်နှံထားအပ်သနည်း။” || “ဂုန်ပါၚ်အဲမဒးဟီုစဟုဲဟှ်ကဵုညးတုဲ နဒဒိုက်သာ်ဝွံဂှ် အဲမဒးဒှ်ရောၚ်သွံ” သၟိၚ်နာ်ဂး။ (ဇ—၅၁၈။ အစွောံ။) = “ငါနှုတ်မစောင့်ဘဲ သူတစ်ပါးအား မိမိ၏လျှို့ဝှက်ချက်ကို ပြောပြလိုက်မိသောကြောင့် ဤကဲ့သို့သောဒုက္ခဖြစ်ရ၏။” || “ပူဂဵုမဂၠံက်သၟာန်ဟုဲဟှ်ညး။” (သၠပတ်စှ်ၜါရာသဳ) = “သူတစ်ပါး၏လျှို့ဝှက်ချက်ကို အစ်နှိုက်မေးမြန်းသောသူ။”')
,(15651,3,9,'၁။ နာမ်ပုဒ်နောက်မှလာ၍ နာမ်ပုဒ်ကိုလေးနက်စေသောစကားလုံး။ ရယ်။ ရေ။ ရဲ့။','“ယွံကောနန္ဒဟိုဲ၊ ကလေၚ်စဴကဵုပြဟ်ညိအဴ” ရဴဝွံဇနပဒကလျာဏဳကော်ဟီု။ (ဇ—၁၈၂။ အစွောံ။) = “နောင်တော်နန္ဒရေ၊ မြန်မြန်ပြန်လာပါနော်” ဟု ဇနပဒကလျာဏဳသည် နန္ဒအားခေါ်ပြော၏။ || “ဟးတေမဳဂၠုယာဲဟိုဲ၊ မိမပလွဳပရာ ပေၚ်အာဂြိုပ် (၂) သၞာံတုဲရသွံလေဝ်ကောန်။” (ဇ—တေမဳ။အစွောံ။) = “အိုမယ်မယ့်သားဦးမောင်တေမိရဲ့၊ သားကို မယ်မယ်လုံ့လပြုခဲ့သည်မှာ (၂) နှစ်တာပြည့်ခဲ့လေပြီတကား။”')
,(15651,3,9,'၂။ ခေါ်သည့်အမည်ရှေ့မှလာ၍ ရှေးရှုခေါ်ရာ­ သုံးသောစကား။ အို။ဟယ်။','“ဟိုဲတၟံ—ဟိုဲတၟံ—ဟိုဲတၟံ” (သာ်ဝွံပိဝါ သၟိၚ်ကၞုဲကော်ဟီုကဵုတၟံလးရ။) (ဇ—၅၇။ အစွောံ။) = “အိုကျောက်ဖျာ၊ အိုကျောက်ဖျာ၊ အိုကျောက်ဖျာ” ဟု ဤသို့သုံးကြိမ် မျောက်မင်းသည်ကျောက်ဖျာအားခေါ်၏။')
,(15652,3,1,'လင့်။ လင့်စၚ်။','“မသိုၚ်ဟဝ်လ္တူဆု။” (အကြီုရာဇာဓိရာဇ်) = “သစ်ပင်ထက်­ လင့်ဆောက်သည်။”')
,(15653,3,1,'၁။ လင်းယုန်ငှက်။ ဝန်လိုငှက်။','“ယာတ်ဂှ် ညးဂွဳဇွ ပ္ဍဲတ္ကအ်ဥတ္တရဂုရုတေံတုဲ ဟဝ်ကၠိုၚ်အာဂွံဂိုၚ်နၚ်—။” (ဇ—၂၂၁။ အစွောံ။) || “ဇၞော်ၜိုပ်ထဝ်ၜါတြုံကဵုဗြဴဝွံ တၟာဗၞတ်ဟဝ်ကၠိုၚ်ဗၠာဲဟေၚ်။” (ရာဇာထ္ၜုတ်) = “ရွှေဟင်္သာမောင်နှံတို့၏အရွယ်ပမာဏကား လင်းယုန်ပျိုပမာဏရှိ၏။”')
,(15653,3,1,'၂။ ကျမ်းဂန်လာငှက်ကြီးတစ်မျိုး။','“ဗတ်ရကလိဂွံဟဝ်ကၠိုၚ် သ္ဂောံက္ဍိုက်ဗက်အာမ္ဂး မရာတ်သ္ဂောံဗၠးမာန်ကီု။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “အကယ်၍ဂဠုန်ငှက်ကိုရ၍ လိုက်ပါစီးနင်းရငြားအံ့ အရှင်မင်းကြီးလွတ်မြောက်နိုင်ရာ၏။” (မင်းပူးဦးသြဘာသ၏မြန်မာမူ­ ‘ဂဠုန်ငှက်’/‘ငှက်ဂဠုန်’ ဟုလာသည်။)')
,(15654,3,1,'သတ္တဝါတစ်မျိုး။ (?)','“ရမျှာၚ်ညံၚ်ကွဴ၊ သော်ရဴဟေဝ်ဟောၚ်။” (လိက်နဲယသမုဒ္ဒြဳ။ အစွောံ။) || “ကာလဒှ်ဗၠာဲ၊ ဂေါဝ်ဆာဲကၞိၚ်ပေါင်။ ရမ်သာၚ်ညံၚ်ကွဴ၊ သော်ရဴဂေါဝ်လှောင်။ စၞာံဇကုသ္အး၊ ညံၚ်ထဝ်ဂၠးရောၚ်။ မတ်သၟာညံၚ်သၞံၚ်၊ ေၚက်ညံၚ်ဟေဟောၚ်။ ထတ်စောံမြက်စာ၊ ဒၞာဲအာဟွံဍောၚ်။” (လိက်တရဳသံသာ)')
,(15655,3,4,'ခြေလက်ကိုဆန့်တန်း၍ လှမ်းယူသည်။','‘ဟောဝ်ၜှ်ပ္ကဴ’ = ‘ပန်းကိုလှမ်းပြီးခူးသည်။’ || “(သၟိၚ်လကဲစှ်ေကဵုဇုက်) ပ္တုံဖျေံဇကု ပ္ဍဲကမၠိုၚ်တုဲ သုၚ်ဍာ်ဒဵုဖဲတုဲ ဟောဝ်ဇုက်ဂှ်ဟွံဂွံတုဲ တိုန်ဟွံမာန် ဒၟံၚ်ပ္ဍဲကမၠိုၚ်ရ။” (ဇ—၂၅၉။ အစွောံ။) = “မင်းသည် ကြိုးဖြင့်တွဲလောင်းဆင်း၍ ရေတွင်းထဲသို့ ကိုယ်ကိုချပြီးလျှင် ရေကိုဝအောင်သောက်၍ ထိုကြိုးကို လှမ်းယူ၍မမှီသဖြင့် မတက်နိုင်ဘဲ ရေတွင်းထဲ­သာနေ၏။” || “သစ္ဆုဂၠိုၚ်တၞံ၊ ဍုဟ်ဗြံဖလ။ ကၞုဲဂၚ်ဟောဝ်ၜှ်၊ ပြဟ်နူသာခ။” (လိက်ဗြရတ်ဣဏၚ်ကၚ်ရဳ) = “များစွာသောသစ်သီးပၚ်မှ မှည့်သောသစ်သီးတို့ကို မျောက်၊မျောက်ညိုတို့ လှမ်းယူခူးရာ အကိုင်းမှကြွေကုန်၏။” || “ညာတ်ပ္ကဴဒကှ်၊ ဟောဝ်ၜှ်ဝေၚ်တဴ။” (လိက်ဘောဂရေန်)')
,(15655,3,1,'အသူ။ တစ်သူ။ (မတ်တတ်ရပ်ထားသောသူ၏ ခြေဖျားမှမြှောက်ထားသောလက်ဖျားအထိ ဖြစ်သောအမြင့်။)','‘မွဲဟောဝ်’ လည်းရှု။')
,(15656,3,4,'(ထဘီ) ဝတ်သည်။','ဟဵုဂၞိန် = ထဘီဝတ်သည်။ || “ဟဵုဂၞိန်ဂိုၚ်အိက်၊ သ္ဂောံတိက်ဗတံ။” (ဗြရတ်ဣဏၚ်ကၚ်ရဳ)')
,(15657,3,1,'၁။ မှက်ကောင်။ မှက်ခြင်။',NULL)
,(15657,3,1,'၂။ သပေါ့ပင်။','‘သ္ၚေအ်’ ရှု။')
,(15658,3,9,'ရော့။ (ပစ္စည်းကို လက်ထိလက်ရောက်ပေးစဉ် ပြောဆိုသောစကား။)','“ယွံဒေံဗြဴ၊ ဟေအ်ဖျုန် စရ။” (ဇ—၁၅၂။ အစွောံ။) = “နှမ၊ ရော့—အသား စားပါလော့။”')
,(15659,3,5,'မ။ မဟုတ်။','ဟွံတီ = မသိ။ || ဟွံအာ = မသွား။ || ဟွံက= မက၊ ပိုလွန်သည်။ || ဟွံပိုတ် = မပြတ်၊ အမြဲ။ || ဟွံမွဲ = မရှိ။ || ဟွံသေၚ် = မဟုတ်။')
,(15660,3,4,'မက။ ပိုလွန်သည်။','‘သီုစိၚ်သၟိၚ်လ္ၚီဟွံကတံဂှ်။’ (ဇ—၄၅၅။ အစွောံ။) = ‘မင်း၏တစ်ထောင်မကသော ဆင်အားလုံးတို့သည်—။’')
,(15661,3,3,'မကောင်းသော။ ဆိုးဝါးသော။','“ဒေသထာန်ဂှ် နွံကဵုကမၠတ်ဒမၠ မဟွံခိုဟ်မဟွံသန် ဝေၚ်ကၠေံတုဲ ဂပ်ဂဝ်တွာ်မိဂ္ဂး။” (သၠပတ်ဒ္ၚောဝ်သၜောံ) = “မကောင်းဆိုးဝါး သူခိုးဓါး ပြများရှိသော အရပ်ဒေသကို ရှောင်ရှား၍ သွားသင့်သည်ဟူလို။”')
,(15662,3,4,'ကြိယာရှေ့မှဆက်၍ မဖြစ်ရသေးမီ၊ မပြုရသေးမီအနက်ကို ဖြစ်စေသည်။အောက်ဖော်ပြပါ ပြယုဂ်များကိုကြည့်ပါ။',NULL)
,(15663,3,4,'မပျက်ရသေးမီ။','“အဲရဂွံအာကၠာမ္ဂး ဂၠံၚ်တြဴလေဝ် ဟွံဂတာပ်လီုဏီ၊ ဍာ်၊အှ်ော၊ သဏေဝ် ပိုဲဟွံဒိုက်ရ။—” ညးဗၞိက်သမၠီုဂှ်ချပ်။ (ဇ—၁။ အစွောံ။) = “ငါသည် ရှေ့မှသွားသည်ရှိသော် မပျက်ရသေးသော လမ်းခရီးဖြင့် သွားရအံ့။ ရေ၊ ထင်း၊ ဟင်းရွက်စသည်လည်း ရရန်မခဲယဉ်းလတ္တံ့” ဟု လှည်းကုန်သည်မိုက်ကြံ၏။')
,(15664,3,4,'မရောက်သေးမီ။ မရောက်သေးခၚ်။','“ဟာဲကမၠတ် မၞုံကဵုဘဲသြံၚ်၊ နူကၠာသ္ကအ်သၟိၚ်ဟွံဂတာပ်စိုပ် ဗှ်ေက္တဵုအာကၠေံညိ။” (ဇ—၃၁၁။ အစွောံ။) = “ဟယ်—တံကျင်လျှို ခြင်းဘေးဒဏ်ရှိသောသူခိုး၊ မင်းချင်းယောကျာ်းတို့ မရောက်သေးခၚ် သၚ်ထသွားလေလော့။”')
,(15665,3,4,'မပြီးစီးသေးမီ။','“ကဵုခၞံပြာသာဒ်ဇၞော်မွဲ — ကၠာနူပြာသာဒ်ဂှ် ဟွံဂတာပ်တုဲညိဂှ် ဒိဋ္ဌမၚ်္ဂလိကာ သၠးကောန်တြုံမွဲ ပ္ဍဲကဏာဂှ်ရ။” (ဇ—၄၉၇။ အစွောံ။) = “ပြာသာဒ်ကြီးကိုဆောက်လုပ်စေ၏။ ပြာသာဒ်မပြီးစီးသေးမီ ဒိဋ္ဌမၚ်္ဂလိကာသည် ထိုမဏ္ဍပ်­သာလျှင် သားကိုဖွား၏။”')
,(15666,3,5,'မကြာမြင့်မီ။ မကြာခင်။','“သၟတ်ၜါဂှ် ဂွံမံၚ်မွဲကရောံကေုာံရၚ်သ္ကံတုဲ ဟွံဂတာပ်လအ် ကလိဂွံကောန်တြုံမွဲရ။” (ဇ—၄၇၉။ အစွောံ။) = “ထို (ချစ်သူ) နှစ်ဦးတို့သည် အတူတကွနေ၍ မကြာမြင့်မီလျှင် သားယောကျာ်းတစ်ယောက်ကို ဖွားမြင်၏။” || “(ပွအမာတ်ဂှ်) ဟွံဂတာပ်လအ် မၞိဟ်သ္အာၚ်တံဂှ်တီစုတ်—။” (ဇ—၇၉။ အစွောံ။) = “ထိုအမတ်၏လုပ်ရပ်သည်မကြာမြင့်မီလျှင် အခြားလူများသိကုန်၏။” || “ကြဴဝွံဟွံဂတာပ်လအ် မိမၜါဂှ် စုတိအာရ။” (ဇ—၃ဝ၁။ အစွောံ။) = “မကြာမြင့်မီ နောက်အဖို့­ မိဘနှစ်ပါးတို့သည် သေလွန်ကုန်၏။” || ‘မသက်ဂတာပ်လအ်’ (ကြိဝိ) လည်းရှု။')
,(15667,3,5,'မချွတ်။ မလွဲမသွေ။ ဨကန်။','“ဂွံပအာတဴဓဝ်သုစရိုတ်တုဲဂှ် ပ္ဍဲပလိုက်ဂှ် ဂွံအာစိုပ်ဍုၚ်သွဝ် ဟွံဆောတ်ရ။” (ဇ—၃၆၂။ အစွောံ။) = “ကောင်းသောအကျင့်သီလကို ကျင့်ခြင်းအားဖြင့် တမလွန်­ နတ်ပြည်သို့ လားရောက်ရမည်မချွတ်။”')
,(15668,3,5,'မနီးမဝေး။',NULL)
,(15669,3,4,'(ကုန်) မှန်းမသိ။ (စဲ) မှန်းမသိ။ (ပြတ်လပ်) မှန်းမသိ။',NULL)
,(15670,3,4,'(မိုး) စဲရမှန်းမသိအောင်ရွာသည်။၊ သည်းထန်စွာ ဆက်တိုက်ရွာသည်။','‘ပ္ဍဲကာလဗြဲဂှ် ဗြဲဇၞော်ဂူဟွံတီဍး။’ (ဇ—၂၅ဝ။ အစွောံ။) = ‘ထိုမိုးကာလ­ မိုးကြီးသည် မရပ်မစဲဆက်တိုက်ရွာသွန်း၏။’')
,(15671,3,4,'ပြတ်မှန်းစဲမှန်းမသိ။ မပြတ်မစဲ အမြဲတည်ရှိသည်။','“မြမောဝ်ဓဝ်သဳလဂှ် မပ္ဍးတၟာဲအာ ဟွံတီဟဲရ။” (ဇ—၃၈၈။ အစွောံ) = “သီလတရားဟူသောမွှေးရနံ့သည် မပြတ်မစဲအမြဲသင်းပျံ့၏။” || “စိုတ်သတ္တံ ဟွံဗိုန်ဟွံဂၠိဟွံထဳတိ ဆမကၠိုက်ကၠိဒၟံၚ် ဟွံတီဟဲရ။” (သၠပတ်ကာလထေ) = “သတ္တဝါတို့၏စိတ်သည် မခိုၚ်မမြဲမတည်တံ့ မပြတ်မစဲ အမြဲညစ်ညမ်းလျက်သာရှိနေ၏။”')
,(15672,3,4,'ကုန်မှန်းမသိ။ ပြည့်မြဲပြည့်နေသည်။','“ယွံကောန်၊ နုၚ်ဒိပ်ဝွံဂှ် မဂၠံက်ကေတ် ဒြပ်ရတ်ဂှ် ဟွံတီအိုတ်ရကောန်။ နုၚ်ဝွံ လ္ပကဵုပါ်ညိ” ဣန်ဂး။ (ဇ—၂၉၁။ အစွောံ။) = “ချစ်သား၊ နတ်­ဖြစ်သောဤအိုးမှ ဥစ္စာရတနာတို့ကို နှိုက်ယူလော့။ ကုန်သွားသည်ဟူ၍မရှိ ပြည့်မြဲပြည့်နေလိမ့်မည်။ ဤအိုးကို မကွဲပါစေနှင့်။”')
,(15673,3,4,'‘ဟွံတီပယာံကာလ’၊ ‘ဟွံတီဗၞတ်ကာလ’ တို့နှင့်အတူတူ။',NULL)
,(15674,3,4,'အချိန်အခါနှင့်နေရာဒေသကို မသိ။ မသွားအပ်သောအချိန်၊ မသွားအပ်သောနေရာဒေသကို မသိမဆင်ခြင်နိုင်။',NULL)
,(15675,3,4,'တန်ဖိုးမဖြတ်နိုင်။','“ဆပိုဲမိၚ်ကၠုၚ်ဂှ် တိဇၞော်ကီု ကၟိန်ဍုၚ်ကီု ဟွံတီကဵုၚုဟ်မးရောၚ်။” (ဇ—၅။ အစွောံ။) = “ရှေး­ငါတို့ကြားဖူးသည်ကား မြေကြီးသည်၄င်း တိုင်းပြည်သည်၄င်း တန်ဖိုးမဖြတ်နိုင်။”')
,(15676,3,4,'အပိုင်းအခြားမသိ။ အတိုင်းအရှည်မသိ။ အလွန်များသည်။','“ရတ်ပိမၞုံဂုန်မဟွံတီကဵုဗၞတ်တွဵု။” (ဇ—၂ဝ၃။ အစွောံ။) = “အပိုင်းအခြားမသိသော ဂုဏ်တော်နှင့်ပြည့်စုံသော ရတနာသုံးပါး။”')
,(15677,3,4,'ရေရေရာရာ မသိသေး။ သေသေချာချာ မသိသေး။','“အဲဒှ်အာဍုၚ်မတ်မလီုဟာဂှ် လၟုဟ်ဟွံတီတိုန်စှ်ေဏီရ။” = “ငါမော်လမြိုင်သွားဖြစ်မလားဆိုတာ ယခုသေသေချာချာမသိသေးပါ။”')
,(15678,3,3,'အစအဆုံးမသိသော။ အရင်းအဖျားမသိသော။ ရောက်တတ်ရာရာဖြစ်သော။','“ဟိုတ်မဗ္ၜူအာ (သုရာ) တုဲ ဂလာန်မဂၠိုၚ် ဟွံတီတမ်ကၞတ်တံဂှ် မဒးဟီုရ။” (ဇ—၅၁၂။အစွောံ။) = “သုရာသောက်၍ယစ်သောကြောင့် များစွာသောစကားကို အရင်းအဖျားမသိရောက်တတ်ရာရာ ပြောဆိုမိရာ၏။”')
,(15679,3,5,'အချိန်အခါကိုမသိဘဲ။ အချိန်အခါမဟုတ်။','“ယွံခမဳတံ၊ ခမဳဂှ် ဗရုပါၚ်ဟွံတီပယာံကာလဂှ် ဆလၟုဟ်ဟွံသေၚ်၊ နူအတိက်တေံတုဲရ” ကျာ်တြဲဂး။ (ဇ—၁၁၉။ အစွောံ။) = “ရဟန်းတို့၊ ယခုအခါ­သာလျှင် ထိုရဟန်းသည် အခါမဟုတ်သည်­ အသံပြုတတ်သည်မဟုတ်သေး။ ရှေး­လည်း အခါမဟုတ်သည်­ အသံပြုတတ်သည်သာလျှင်တည်း။” (ညောင်ကန်) || “ဟွံတီဗၞတ်ကာလ” နှင့်အတူတူ။')
,(15680,3,4,'ဘုမသိဘမသိ။ ဘာမျှမသိနားမလည်။','“ပူဂိုလ်ဟွံတီပိၜါ။” (ပြကိုဟ်မ္ၚိုလ်ပိစှ်ောဒစာံ) = “ဘုမသိဘမသိသောသူ။”')
,(15681,3,4,'(ကြိုက်နှစ်သက်လွန်း၍) စိတ်တွင်မရောင့်ရဲနိုင်ဖြစ်သည်။','“ဂွံဗှ်ကေတ်ဇၟန်လိက်မန်ကျာ်ဇၞော်အစွောံဂှ် နွံကဵုရှ်သာလောန် ဗှ်ဟွံတီဖဲစိုတ်ရ။” = “ဝေါဆရာတော်ဘုရား၏ မွန်စာပေအရေးအသားကို ဖတ်ရှုရသည်မှာ အလွန်အရသာရှိလှသည်။ ဖတ်၍မရောင့်ရဲနိုင်အောင်ဖြစ်သည်။” || “ဗဵုဒ္ၚောဝ်တဴဟွံတီဖဲ ဟွံတီဟဲစိုတ်။” (ဇ—မဟောဟ်သဓ။ အစွောံ။) = “ရှုစား၍မဝနိုင် မရောင့်ရဲနိုင်။”')
,(15682,3,4,'ကြည့်၍မဝနိုင်။ ရှု၍မရောင့်ရဲနိုင်။','“မၞိဟ်မကၠုၚ်တံဂှ် ညာတ်ရုပ်သၟတ်ဗြဴဂှ်တုဲ ဗဵုဟွံတီဖဲမတ်ရ။” (ဇ—၃၈၇။ အစွောံ။) = “လာရောက်ကုန်သောလူတို့သည် ထိုမိန်းမပျို၏ရုပ်အဆင်းကိုမြင်၍ ကြည့်၍မဝနိုင် ရှု၍မရောင့်ရဲနိုင်အောင်ရှိကြ၏။”')
,(15683,3,4,'အတိုင်းအရှည်ကိုမသိ။ ပမာဏကိုမသိ။ ဖြစ်သင့်သောစည်းကိုကျော်လွန်သည်။','“ညးဗၞိက်တမၠာတေံဂှ် ဟွံတီဗၞတ်တုဲ ဒလောအ်ဗ္တောန်တၠပညာလေဝ် ဟွံကေတ်ဟွံဒ္ဂေတ်ဗက်တုဲ ဒှ်လေၚ်တုဲရ” ကျာ်တြဲဂး။ (ဇ—၂၅၆။ အစွောံ။) = “ရှေးသူဟောင်းတို့သည်ကား မရောင့်ရဲကုန်၍ အတိုင်းအရှည်ကိုမသိကုန်၍ ပညာရှိတို့၏စကားကို နားမထောင်ကုန်၍အသက်ကုန်ခြင်းသို့ ရောက်ကုန်သလျှင်ကတည်း” ဟုမိန့်တော်မူ၏။ (ညောင်ကန်) || “(ကောန်သေဋ္ဌဳဂှ်) တ္ၜူမာဲတဴကဵုဗြဴ တ္ၜူမာဲတဴကဵုသုရာ တ္ၜူမာဲတဴကဵုဖျုန် — ရပ်စပ်ဟွံတီဗၞတ်ဗ္ၜတ်တုဲ လ္ပာ်ဇိက်ဗၞိက်ဇမၞော်ပၟဝ်ဂှ် ဟၟဲသက်က်တုဲ—။” (ဇ—၂၉၁။ အစွောံ။) = “ထိုသူဋ္ဌေးသားသည် မိန်းမကြူးခြင်း၊ သုရာကြူးခြင်း၊ အသားစားကြူးခြင်းဖြင့် စည်းမရှိကမ်းမရှိသုံးဖြုန်း၍ ကုန်သွယ်ခြင်းဥစ္စာပွားများခြင်း လုံးဝမရှိ—။” || “ဟိုတ်သၟိၚ်ဂှ်မဒှ်အဓမ္မ ကေတ်အခေါန်ဖလှာ ဟွံတီဗၞတ်ဗ္ၜတ်တုဲဍုၚ်ကွာန်ကတဴရ။” (ဇ—၅၂ဝ။ အစွောံ။) = “ထိုမင်းသည် အဓမ္မမင်းပြု၍ အခွန်အတုတ်ကို အတိုင်းအတာထက်လွန်၍ ကောက်ယူသဖြင့် မြို့ရွာဆူပူ၏။”')
,(15684,3,4,'အချိန်အခါကိုမသိ။ အချိန်အပိုင်းအခြားကိုမသိ။','“စဟွံတီဗၞတ်ကာလမ္ဂးမလေပ်က္တဵုဒှ်ယဲရ။”= “အချိန်အခါကိုမသိဘဲ စားခြင်းသည် ရောဂါဖြစ်စေတတ်သည်။” || ‘တီဗၞတ်ကာလ’ ရှု။')
,(15685,3,4,'မိမိ၏အစွမ်းအစ (အရည်အချင်း) ပမာဏကိုမသိ။မိမိကိုယ်ကို အထင်ကြီးလွန်းသည်။','“ဟာဲသဒိုဟ်သမ္ဒီု၊ ဗှ်ေဟွံတီဗၞတ်ဇကုဗှ်ေတုဲ ဗှ်ေပြိုၚ်ဝေၚ်ကဵုအ္စာသွံ။” (ဇ—၂၃၁။ အစွောံ။) = “ဟယ်သူမိုက်သူယုတ်၊ နင့်အစွမ်းအစပမာဏကို နၚ်မသိဘဲ ဆရာနှင့်တကွ ထွက်ယှဉ်ပြိုင်ဘိ၏။” || “ဟာဲတ္ၚေက်၊ ဗၞတ်ဇကုဗှ်ေ ဗှ်ေဟွံတီသွံ။ ဗှ်ေဒၠောံဗ္တောန်အဲပၠန်ရောၚ်သွံ” ဗမၞိဟ်ဗြဴဂး။ (ဇ—၁၉၈။ အစွောံ။) = “(ဟယ်ကျေးသား) ၊ သင်သည် ငါ့ကိုဆိုဆုံးမ၏။ မိမိ၏ပမာဏကိုမသိ။” (ညောင်ကန်) || “(ထေဗျုဂှ် ပ္ဍဲအတိက်မဒှ်ကၠိက်တေံလေဝ်) အစောံဒြဟတ်ဇကုအောန် သဒိုဟ်သဒီုတဴဂှ် ဟွံတီဗၞတ်အစောံဇကုတုဲ ပ္ဍဲကဵုညးမၞုံကဵုဣဓိအစောံဒြဟတ် ပ္ကီုဝါဒတုဲ မဒးလေတ်ဒၟံၚ် ပ္ဍဲအသုဘတုဲရ။” (ဇ—၁၅၃။ အစွောံ။) = “ရှေး (တောဝက်ဖြစ်စဉ်ကာလ) ­လည်း ထိုရဟန်းအိုသည် လျှပ်ပေါ်သည်ဖြစ်၍ မိမိ၏အစွမ်းကို မသိလေ၍ အစွမ်းကြီးကုန်သောသူတို့နှင့်တကွ ပြိုင်ဆိုင်၍ မစင်အလိမ်းလိမ်းကပ်ဘူးလေပြီ။” (ညောင်ကန်)')
,(15686,3,16,'ပမာဏအပိုင်းအခြားမသိ။ အတိုင်းအရှည်မသိ။ အတိုင်းအဆမသိ။ မရေမတွက်နိုင်။','“သၟိၚ်ပ္တုဲဒါန်ဟွံတီကဵုဗၞတ်တွဵုရ။” (ဇ—၄၁၅။ အစွောံ။) =“မင်းသည် အတိုင်းအရှည်မသိ အလှူဒါနပြု၏။” || “(ဗမၞိဟ်ဗြဴဂှ်) ပတွဵုနူဗမၞးမအာကၠေံတုဲ တြုံမကၠုၚ်ကီု တြုံတံမအာကီု ဟွံတီကဵုဗၞတ်တွဵုရ။” (ဇ—၁၉၈။ အစွောံ။) = “ထိုပုဏ္ဏေးမသည် ထိုပုဏ္ဏား၏ထွက်သွားသောကာလမှစ၍ — လာကုန်သောယောကျာ်းတို့၏၄င်း သွားကုန်သောယောကျာ်းတို့၏၄င်း အတိုင်းအရှည်သည်မရှိ။” (ညောင်ကန်) || “ရတ်ပိမၞုံဂုန်မဟွံတီကဵုဗၞတ်တွဵု။” (ဇ—၂ဝ၃။ အစွောံ။) = “အတိုင်းအရှည်မသိ (အပိုင်းအခြားမသိ) သော ရတနာသုံးပါး၏ ဂုဏ်ကျေးဇူးတော်။”')
,(15687,3,4,'မပြုအပ်သည်ကိုပြုသည်။ အကြံအစည်ပမာဏကိုမသိ။ လျှပ်ပေါ်သည်။','“ပူဂဵုဟွံတီဗၞတ်ပြဝဂှ်တုဲ မဒးချိုတ်သ္တိက်ဒၟံၚ်ရ။” (ဇ—၃၃၅။ အစွောံ။) = “ပမာဏကိုမသိဘဲ မပြုအပ်သည်ကိုပြုသဖြင့် လျောင်းလျက်သေရ၏။”')
,(15688,3,4,'လောဘပမာဏကိုမသိ။ အလွန်လောဘကြီးသည်။','‘တီဗၞတ်လောဘ’ရှု။')
,(15689,3,4,'စကားပမာဏကိုမသိ။ စကားများသည်။','“ပ္ဍဲသၟိၚ်တၠကုသဵုၜါ မဟီုပၠန်ဂတးတဴဂှ် ယာံရအဲဟီုသြံက်တိုန်ပၠန်မ္ဂးဂှ် အဲဒှ်အာပူဂဵုအရိုၚ်အဇိုၚ် ဟွံတီဗၞတ်အရေဝ်ဂှ်ပၠန်ရ။” (ဇ—၅၃၃။ အစွောံ။) = “ဘုန်းကံရှင်မင်းနှစ်ပါးတို့ စကားတုံ့လှယ်ပြောဆိုနေကြစဉ် အကျွန်ုပ်ဝၚ်တော (ဝၚ်စွက်) ပြောဆိုပါက အကျွန်ုပ်သည် စကားပမာဏကိုမသိသော ရိုင်းစိုင်းသောသူဖြစ်သွားလိမ့်မည်။”')
,(15690,3,4,'အမှားအမှန်ကိုမသိ။ မှား၏မှန်၏ ဘာမျှမသိ။ အသည်။တုံးသည်။','“ဍေံသ္ဒီုတုဲ ဍေံမဟွံတီမုတ်ဒွးရ။” (ဇ—၄၄၃။ အစွောံ။) = “သူသည်မိုက်မဲ၍ အမှားအမှန်ကို ဘာမျှမသိ။” || “(သတ်ဗဳလမုဟ်ပြဟ်စှ်ေ ဒးသၠတာဇမ်ကှ်ဂှ် တိကၠိုဟ်ဂတးအာဂးတုဲ) ရဴဗတာဲဖေက်သၟး ဟွံတီမုတ်ဒွးမွဲသာ်ဂှ်ကီု။” (ဇ—၃၂၂။ အစွောံ။) = “ဥသျှစ်သီးမှည့်ကြွေ၍ထန်းလက်ခြောက်ပေါ်ကျသည်ကို မြေပြိုသည်ထင်မှတ်၍ အကြောက်သက်သက် မှား၏မှန်၏ဟူ၍ ဘာမျှမသိသော ယုန်သူငယ်ကဲ့သို့။”')
,(15691,3,4,'အပြုအမူ၊ လုပ်ရပ်စသည် မမှန်ကန်။','“သဘဴကောန်မ္ဂး စှ်ေစးဂလာန်မိကဵုမမ္ဂး ဟွံဒးပွသွံ။” (ဇ—၂၄၃။ အစွောံ။) = “သားသမီးမည်သည် မိဘစကားကို လွန်ဆန်ခြင်းသည် မမှန်ပါလား။”')
,(15692,3,4,'နောက်မလုပ်တော့။ နောင်ခါမလုပ်တော့။','“ပွမယုတ်မာသာ်ဝွံ အဲဟွံပကြဴရ။” =“ဤကဲ့သို့ယုတ်မာသောအမှုကို နောင်ခါငါမလုပ်တော့ပါ။”')
,(15693,3,4,'မျက်ကွယ်ပြုသည်။ မသိကျိုးကျွံပြုသည်။ လျစ်လျူရှုသည်။',NULL)
,(15694,3,4,'မသိကျိုးကျွံပြုသည်။ မသိဘဲနေသည်။','“ပယာံကာလဝွံ အဲဂပ်ဂဝ်အာကတ်ဇရေၚ်အ္စာရောၚ်၊ ပယာံကာလဝွံ အဲဂပ်ဂဝ်ဖဍောတ်သှ်ၛာဲရောၚ်မ္ဂးဂှ် ခမဳဂှ် ဟွံပတီသက်က်ရ။” (ဇ—၁၁၉။ အစွောံ။) = “ဤကာလ­ ငါသည် ဆရာ့အထံတွင် တရားကျမ်းဂန်သၚ်ခြင်းကို ပြုအပ်၏၊ ဤကာလ­ ငါသည် ရွတ်ဖတ်သရဇ္ဈယ်အပ်၏ဟု ထိုရဟန်းသည် မသိဘဲနေ၏။” || “ဒဒိုက်စိုတ်အဲမစံၚ်တူဒၟံၚ်ဂှ် ဂၞကျာ်ဟွံပတီရ” သၟိၚ်ဂး။ (ဇ—၃၁၄။ အစွောံ။) = “ငါ၏စိတ်ပူပန်နေခြင်းကို သၚ်မိဖုယားသည် မသိကျိုးကျွံပြုလျက်နေဘိ၏” ဟုမင်းဆို၏။')
,(15695,3,4,'အရေးမလုပ်။ ဂရုမစိုက်။ ဂရုမထား။ နှလုံးမသွင်း။','“ဍေံဟိုတ်မာဲဒၟံၚ် ဍေံဟွံပမန။” (ဇ—၄၇၂။ အစွောံ။) = “သူသည် မေ့လျော့ပေါ့ဆ၍ ဂရုမထား။”')
,(15696,3,4,'ဂရုမစိုက်။ အရေးမလုပ်။ အဖက်မလုပ်။','‘ပအလေဝ်’ တွင်ရှု။')
,(15697,3,4,'(ဆူညံသံကြောင့်) ဘာမျှမကြားရဖြစ်သည်။','“သီုၜိုပ်ဒစိတ်စှ်ောလ္ၚီဂှ် ဗိုၚ်ဟုပ်ဂကောံဗောဓိသတ် (သၟိၚ်ၜိုပ်ထဝ်) တုဲ ဗရုဝေါဟာဘာသာဂလာန်ၜိုပ်တံဂှ် ဂၠိုၚ်လောန်တုဲ ဟွံမိၚ်ပလိုတ်ဗမံက်ရ။” (ဇ—၅၃၄။ အစွောံ။) = “ထိုကိုးသောင်းကုန်သော ဟင်္သာအပေါင်းတို့သည်ဘုရားလောင်းရွှေဟင်္သာသာမင်းထံ စုအုံရောက်ရှိလာကာ မိမိတို့ဟင်္သာဘာသာစကားဖြင့်အော်မြည်သော များစွာသောအသံကြောင့် ဘာမျှမကြားရဘဲရှိ၏။”')
,(15698,3,4,'မရှိ။',NULL)
,(15699,3,9,'(နာမ်ရှေ့ဆက်) နာမဝိသေသနဖြစ်စေသောစကား။','ဟွံမွဲကဵုမိမ = မိဘမရှိသော။ || ဟွံမွဲကဵုသ္ၚိဋ္ဌာန် = အိမ်ရာမရှိသော။ || ဟွံမွဲကဵုၚုဟ်မး = တန်ဖိုးမရှိသော။ || ဟွံမွဲကဵုကွတ်ဗ္တောန် = အတတ်ပညာမရှိသော။')
,(15700,3,4,'လုံးဝမကျန်ဘဲ ကုန်ခန်းသည်။ ပြောင်တလင်းခါသည်။','“ပ္ဍဲဇရာံသြောံဟၟဲသ္အးဒၟံၚ်ရ။” (ဇ—၁၉၉။ အစွောံ။) = “ကျီထဲတွင် စပါးမရှိ ပြောင်တလင်းခါနေသည်။” || “ဂၠာဲရံၚ်အလုံသ္ၚိဂှ် ဆဗၞတ်သ္ၚုမွဲမကီုလေဝ် ဟၟဲသ္အးဒၟံၚ်ရ။” (ဇ—၃၄ဝ။ အစွောံ။) = “အိမ်လုံးအနှံ့လိုက်ရှာကြည့်ရာ ဆန်တစ်စေ့မျှလည်း လုံးဝမရှိပြောင်ရှင်းနေ၏။” || ‘အိုတ်သ္အး’ လည်းရှု။')
,(15701,3,5,'မယုတ်မလွန်။ မပိုမလို။',NULL)
,(15702,3,7,'၁။ တစ်ခုမဟုတ်တစ်ခုဖြစ်ခြင်းကိုပြသည်။ သို့မဟုတ်။ ထိုသို့မဟုတ်မူကား။','“ဂုန်ဓဝ်သဳလအဲဝွံဂှ် သၟိၚ်သ္ဍိုက်အဲဟာ၊ ဟွံသေၚ်ဂုန်ဂကူပြဲအဲလေဝ်ကဵုဒှ် ဟွံသေၚ်ဂုန်အဲလေပ်ကွတ်ဗိုတ်ပိဗေဒၚ်ပန်ဂှ် သၟိၚ်သ္ဍိုက်အဲဟာ ဒဒှ်ဂှ် အဲစံၜတ်ညိ” ဗမၞးဂှ်ချပ်။ (ဇ—၈၆။ အစွောံ။) =“ငါ၏သီလဂုဏ်ကျေးဇူးကြောင့် မင်းသည် ငါ့ကိုမြတ်နိုးသလော။ သို့မဟုတ် ငါ၏အမျိုးမြတ်သောဂုဏ်ကြောင့်၊ သို့မဟုတ် ငါ၏ဗေဒင်သုံးပုံအတတ်ကို တတ်မြောက်သောဂုဏ်ကြောင့် မင်းသည် ငါ့ကိုမြတ်နိုးသလော၊ သိအောင်ငါစုံစမ်းအံ့” ဟုပုဏ္ဏားကြံ၏။')
,(15702,3,7,'၂။ တစ်ခုမဟုတ်တစ်ခုဖြစ်ခြင်းကိုပြသည်။ သော်လည်းကောင်း။','“ဍာ်မကတဴလောန်ဗၞတ်ဂှ် ဟွံစမ်ၜတ်သုၚ်စုတ် ဗွဲပြဟ်ပြေဟ်ဂှ် ဟွံသေၚ်ပါၚ်တူရ၊ ဟွံသေၚ်တဲတူရ။” (ဇ—၁၅၂။ အစွောံ။) = “ပူလွန်းသောရေကိုမစုံစမ်းမူ၍ အလျင်စလိုသောက်မိက ပါးစပ်သော်လည်းကောင်း လောင်လိမ့်မည်၊ လက်သော်လည်းကောင်း လောင်လိမ့်မည်။”')
,(15703,3,9,'(နာမ်ရှေ့ဆက်) နာမဝိသေသနဖြစ်စေသောစကား။','ဟွံသေၚ်ကဵုဗဗွဲဓဝ် =မတရားဖြစ်သော။ တရားသဖြင့်မဟုတ်သော။ || ဟွံသေၚ်ကဵုမၞိဟ် = လူမဟုတ်သော။ || ဟွံသေၚ်ကဵုကာလ = အချိန်အခါမဟုတ်သော။ || ဗြဴဂူဟွံသေၚ်ကဵုကာလ = အချိန်ကာလမဟုတ်ဘဲ မိုးရွာသည်။ || “ယွံဥပးတံ၊ ပ္ဍဲမဟွံသေၚ်ကဵုကာလဂှ် မူဟိုတ်မကၠုၚ်ရော” ကျာ်တြဲဂး။ (ဇ—၁၈၇။ အစွောံ။) = “ဒကာတို့၊ အဘယ့်ကြောင့် အခါမဟုတ်သည်­ လာကြကုန်သနည်း။”')
,(15704,3,7,'သို့မဟုတ်။ သို့တည်းမဟုတ်။','“စပုၚ်ညိ ဟွံသေၚ်သာ်ဂှ် စကွာၚ်ညိ။”= “ထမင်းစားပါ သို့တည်းမဟုတ် မုန့်စားပါ။” || “အာကျာ်မ္ဂး ပၞာၚ်ဟွံသေၚ်သာ်ဂှ်ပ္ကဴ မမိက်ကဵုမွဲမွဲသာ် ကေတ်ဏာညိ။” = “ဘုရားသွားလျှင် ဖရောင်းတိုၚ်သို့မဟုတ်ပန်း တစ်ခုခုယူသွားပါ။”')
;